/* محادثات إضافية (ب): مواقف يومية متنوّعة + حوارات دعوية بين داعية مسلم وغير مسلم */
window.LEARN = window.LEARN || {};
LEARN.CONV = (LEARN.CONV || []).concat([

  /* ===== مواقف يومية ===== */

  { id: "cv40", lv: "A1", ic: "✂️", t: "En la barbería", tar: "في محلّ الحلاقة", roles: ["الحلّاق", "الزبون"], d: [
    "A:¡Buenos días! ¿Qué desea?|صباح الخير! ماذا تريد؟",
    "B:Buenos días. Quiero cortarme el pelo, por favor.|صباح الخير. أريد أن أقصّ شعري من فضلك.",
    "A:Muy bien. Siéntese aquí. ¿Cómo lo quiere?|حسنًا. اجلس هنا. كيف تريده؟",
    "B:Corto a los lados y un poco largo arriba.|قصيرًا على الجانبين وطويلًا قليلًا من الأعلى.",
    "A:Vale. ¿Y la barba?|حسنًا. واللحية؟",
    "B:La barba no, gracias. Me gusta así.|اللحية لا، شكرًا. أحبّها هكذا.",
    "A:Perfecto. Mire el espejo. ¿Está bien así?|ممتاز. انظر في المرآة. هل هو جيّد هكذا؟",
    "B:Sí, está muy bien. ¿Cuánto es?|نعم، جيّد جدًّا. كم الحساب؟",
    "A:Son doce euros.|اثنا عشر يورو.",
    "B:Aquí tiene. Muchas gracias. ¡Hasta luego!|تفضّل. شكرًا جزيلًا. إلى اللقاء!"
  ] },

  { id: "cv41", lv: "A2", ic: "🧳", t: "Equipaje perdido", tar: "الأمتعة المفقودة", roles: ["موظّفة المطار", "المسافر"], d: [
    "A:Buenas tardes. ¿En qué puedo ayudarle?|مساء الخير. كيف يمكنني مساعدتك؟",
    "B:Buenas tardes. Mi maleta no ha llegado. He esperado una hora.|مساء الخير. حقيبتي لم تصل. انتظرتُ ساعة.",
    "A:Lo siento mucho. ¿De dónde viene su vuelo?|أنا آسفة جدًّا. من أين جاءت رحلتك؟",
    "B:De Casablanca. El número de vuelo es el AT970.|من الدار البيضاء. رقم الرحلة AT970.",
    "A:¿Me deja su tarjeta de embarque y la etiqueta de la maleta?|هل تعطيني بطاقة الصعود إلى الطائرة وملصق الحقيبة؟",
    "B:Sí, aquí están.|نعم، ها هما.",
    "A:¿Cómo es la maleta?|كيف تبدو الحقيبة؟",
    "B:Es grande, azul oscuro, con una cinta verde en el asa.|كبيرة، زرقاء داكنة، وعلى مقبضها شريط أخضر.",
    "A:Gracias. Parece que la maleta se ha quedado en Madrid. Llegará mañana en el primer vuelo.|شكرًا. يبدو أن الحقيبة بقيت في مدريد. ستصل غدًا في أوّل رحلة.",
    "B:¿Me la pueden llevar al hotel?|هل يمكنكم إيصالها إليّ في الفندق؟",
    "A:Sí, claro. Escriba aquí la dirección y su teléfono, por favor.|نعم بالطبع. اكتب هنا العنوان ورقم هاتفك من فضلك.",
    "B:De acuerdo. Muchas gracias por su ayuda.|حسنًا. شكرًا جزيلًا على مساعدتك."
  ] },

  { id: "cv42", lv: "B1", ic: "📋", t: "La reunión de la asociación de padres", tar: "اجتماع جمعية أولياء الأمور", roles: ["رئيسة الجمعية", "وليّ أمر"], d: [
    "A:Buenas tardes a todos. Gracias por venir a la reunión de la asociación de madres y padres.|مساء الخير جميعًا. شكرًا على حضوركم اجتماع جمعية أولياء الأمور.",
    "B:Buenas tardes. Soy Khalid, el padre de Sara, de tercero.|مساء الخير. أنا خالد، والد سارة، من الصفّ الثالث.",
    "A:Bienvenido, Khalid. Hoy queremos organizar la excursión de fin de curso.|أهلًا بك يا خالد. نريد اليوم تنظيم رحلة نهاية العام الدراسي.",
    "B:¡Qué bien! ¿Adónde pensáis ir?|رائع! إلى أين تفكّرون في الذهاب؟",
    "A:Hemos pensado en una granja escuela, a una hora de la ciudad.|فكّرنا في مزرعة تعليمية على بُعد ساعة من المدينة.",
    "B:Me parece una idea estupenda. ¿Necesitáis voluntarios para acompañar a los niños?|تبدو لي فكرة رائعة. هل تحتاجون إلى متطوّعين لمرافقة الأطفال؟",
    "A:Sí, nos faltan por lo menos cuatro adultos. ¿Podría usted venir?|نعم، ينقصنا أربعة بالغين على الأقلّ. هل يمكنك أن تأتي؟",
    "B:Con mucho gusto. Solo una pregunta: ¿cada niño lleva la comida de casa?|بكلّ سرور. سؤال واحد فقط: هل يُحضر كلّ طفل طعامه من البيت؟",
    "A:Sí, cada familia prepara el almuerzo, así que no habrá problemas con las dietas especiales.|نعم، كلّ أسرة تُعِدّ الغداء، لذا لن تكون هناك مشكلة مع الأنظمة الغذائية الخاصّة.",
    "B:Perfecto. ¿Y cuánto costará la excursión?|ممتاز. وكم ستكلّف الرحلة؟",
    "A:Unos quince euros por niño, con el autobús incluido. Si alguna familia tiene dificultades, la asociación ayuda.|نحو خمسة عشر يورو لكلّ طفل، شاملةً الحافلة. وإن واجهت أسرةٌ صعوبات فإنّ الجمعية تساعدها.",
    "B:Me parece muy justo. Contad conmigo.|يبدو لي ذلك عادلًا جدًّا. اعتمدوا عليّ."
  ] },

  { id: "cv43", lv: "A2", ic: "🍳", t: "Cocinamos juntos", tar: "نطبخ معًا", roles: ["الأمّ", "الابن"], d: [
    "A:Adam, ¿me ayudas a preparar la cena?|يا آدم، هل تساعدني في تحضير العشاء؟",
    "B:¡Claro, mamá! ¿Qué vamos a cocinar?|بالطبع يا أمّي! ماذا سنطبخ؟",
    "A:Una tortilla de patatas y una ensalada.|تورتيلا البطاطس وسلطة.",
    "B:¡Qué rico! ¿Qué hago yo?|ما ألذّ ذلك! ماذا أفعل أنا؟",
    "A:Primero lávate las manos. Después pela las patatas, con cuidado.|أوّلًا اغسل يديك. ثمّ قشّر البطاطس بحذر.",
    "B:Ya está. ¿Las corto en trozos?|انتهيت. هل أقطّعها قطعًا؟",
    "A:Sí, pequeños y finos. Yo voy a batir los huevos.|نعم، صغيرة ورقيقة. وسأخفق أنا البيض.",
    "B:¿Cuánto aceite echamos en la sartén?|كم من الزيت نضع في المقلاة؟",
    "A:Bastante, pero no toques la sartén; está muy caliente.|كمّية وافرة، لكن لا تلمس المقلاة؛ إنّها ساخنة جدًّا.",
    "B:Vale. Mientras tanto, corto los tomates para la ensalada.|حسنًا. في هذه الأثناء أقطّع الطماطم للسلطة.",
    "A:¡Muy bien! Eres un gran ayudante.|أحسنت! أنت مساعد رائع.",
    "B:Gracias. ¿Puedo poner la mesa también?|شكرًا. هل يمكنني أن أُعِدّ المائدة أيضًا؟"
  ] },

  { id: "cv44", lv: "C1", ic: "💶", t: "Pedir un aumento de sueldo", tar: "طلب زيادة في الراتب", roles: ["المديرة", "الموظّف"], d: [
    "A:Pasa, Tariq. Me dijiste que querías hablar conmigo. ¿De qué se trata?|تفضّل يا طارق. قلتَ إنّك تريد التحدّث معي. ما الموضوع؟",
    "B:Gracias por recibirme. Quería plantearte la posibilidad de revisar mi salario.|شكرًا لاستقبالي. أردتُ أن أطرح عليكِ إمكانية مراجعة راتبي.",
    "A:Entiendo. Cuéntame en qué te basas.|أفهم. أخبرني على ماذا تستند.",
    "B:En los dos últimos años he asumido la coordinación del equipo de análisis, aunque mi categoría sigue siendo la misma.|في السنتين الأخيرتين تولّيتُ تنسيق فريق التحليل، مع أنّ درجتي الوظيفية بقيت كما هي.",
    "A:Es cierto que tu papel ha cambiado bastante. ¿Tienes datos concretos?|صحيح أنّ دورك تغيّر كثيرًا. هل لديك بيانات محدّدة؟",
    "B:Sí. El proyecto de automatización que dirigí redujo los tiempos de entrega en un treinta por ciento. Además, he revisado los salarios de mercado para puestos similares.|نعم. مشروع الأتمتة الذي أدرتُه قلّص أوقات التسليم بنسبة ثلاثين في المئة. كما راجعتُ رواتب السوق للوظائف المماثلة.",
    "A:Valoro mucho que vengas preparado. No obstante, el presupuesto de este año ya está cerrado.|أقدّر كثيرًا أنّك جئتَ مستعدًّا. ومع ذلك فإنّ ميزانية هذا العام قد أُقفلت.",
    "B:Lo comprendo. ¿Sería viable estudiarlo de cara al próximo ejercicio, o valorar mientras tanto otras fórmulas, como formación o flexibilidad horaria?|أتفهّم ذلك. هل يمكن دراسة الأمر للسنة المالية القادمة، أو النظر في هذه الأثناء في صيغ أخرى كالتدريب أو مرونة ساعات العمل؟",
    "A:Me parece una propuesta razonable. Déjame que lo consulte con dirección y lo retomamos en la evaluación de diciembre.|يبدو لي اقتراحًا معقولًا. دعني أستشير الإدارة ونعود إليه في تقييم ديسمبر.",
    "B:Perfecto. Te enviaré un breve informe con los resultados para que lo tengas por escrito.|ممتاز. سأرسل إليكِ تقريرًا موجزًا بالنتائج ليكون لديكِ مكتوبًا.",
    "A:De acuerdo. Y gracias por plantearlo con tanta claridad y profesionalidad.|اتّفقنا. وشكرًا لأنّك طرحتَه بكلّ هذا الوضوح والمهنية.",
    "B:Gracias a ti por escucharme.|بل شكرًا لكِ على الإصغاء إليّ."
  ] },

  { id: "cv45", lv: "B2", ic: "🏢", t: "Un malentendido con el vecino", tar: "سوء تفاهم مع الجار", roles: ["الجار", "يوسف"], d: [
    "A:Perdone, ¿es usted el vecino del cuarto?|عذرًا، هل أنت جار الطابق الرابع؟",
    "B:Sí, soy Yusuf. ¿Ocurre algo?|نعم، أنا يوسف. هل حدث شيء؟",
    "A:Pues sí. Desde hace varias noches se oyen golpes y ruidos muy tarde, y no consigo dormir.|في الحقيقة نعم. منذ عدّة ليالٍ تُسمَع طرقات وضجيج في وقت متأخّر جدًّا، ولا أستطيع النوم.",
    "B:Lo siento muchísimo, pero le aseguro que nosotros nos acostamos temprano. ¿A qué hora suele ser?|آسف جدًّا، لكنّي أؤكّد لك أنّنا ننام مبكّرًا. في أيّ ساعة يحدث ذلك عادةً؟",
    "A:Hacia las dos de la madrugada. Suena justo encima de mi dormitorio.|نحو الثانية بعد منتصف الليل. يُسمَع فوق غرفة نومي تمامًا.",
    "B:Qué raro... ¡Ah, ya sé! Puede que sea la lavadora: la programamos por la noche porque la luz es más barata.|غريب... آه، عرفت! ربّما تكون الغسّالة: نبرمجها ليلًا لأنّ الكهرباء أرخص.",
    "A:¡Vaya! No se me había ocurrido. Yo pensaba que estaban moviendo muebles.|عجبًا! لم يخطر ذلك ببالي. كنت أظنّ أنّكم تحرّكون الأثاث.",
    "B:Le pido disculpas por las molestias. A partir de hoy la pondremos antes de las diez.|أعتذر إليك عن الإزعاج. ابتداءً من اليوم سنشغّلها قبل العاشرة.",
    "A:Se lo agradezco de verdad. Y perdone si he sonado un poco brusco al principio.|أشكرك حقًّا. وسامحني إن بدوتُ فظًّا قليلًا في البداية.",
    "B:No se preocupe, es normal estar molesto si no se duerme bien. Lo importante es que lo hemos hablado.|لا تقلق، من الطبيعي أن ينزعج المرء إذا لم ينم جيّدًا. المهمّ أنّنا تحدّثنا في الأمر.",
    "A:Tiene razón. Más vale hablar a tiempo que guardar rencor.|معك حقّ. الحديث في وقته خير من حمل الضغينة.",
    "B:Exacto. Y si algún día necesita algo, ya sabe dónde estamos.|بالضبط. وإن احتجتَ شيئًا يومًا ما، فأنت تعرف أين نحن."
  ] },

  { id: "cv46", lv: "B1", ic: "🤲", t: "Voluntariado en el banco de alimentos", tar: "التطوّع في بنك الطعام", roles: ["المنسّقة", "المتطوّع"], d: [
    "A:Hola, ¿eres el nuevo voluntario? Soy Marta, la coordinadora.|مرحبًا، هل أنت المتطوّع الجديد؟ أنا مارتا، المنسّقة.",
    "B:Sí, me llamo Bilal. Me apunté por internet la semana pasada.|نعم، اسمي بلال. سجّلتُ عبر الإنترنت الأسبوع الماضي.",
    "A:¡Bienvenido! ¿Habías hecho voluntariado antes?|أهلًا بك! هل سبق لك أن تطوّعت؟",
    "B:Sí, en mi país ayudaba a repartir comida durante Ramadán. Me gusta mucho ayudar a la gente.|نعم، في بلدي كنت أساعد في توزيع الطعام خلال رمضان. أحبّ كثيرًا مساعدة الناس.",
    "A:Genial. Hoy vamos a clasificar los alimentos que han llegado de los supermercados.|رائع. اليوم سنفرز الأغذية التي وصلت من المتاجر الكبرى.",
    "B:¿Cómo los clasificamos?|كيف نفرزها؟",
    "A:Por tipo: legumbres, conservas, leche y productos de higiene. Y hay que mirar siempre la fecha de caducidad.|حسب النوع: البقوليات والمعلّبات والحليب ومنتجات النظافة. ويجب دائمًا التحقّق من تاريخ انتهاء الصلاحية.",
    "B:Entendido. ¿Qué hacemos con los productos caducados?|مفهوم. ماذا نفعل بالمنتجات منتهية الصلاحية؟",
    "A:Los ponemos en esa caja roja. No se pueden repartir.|نضعها في ذلك الصندوق الأحمر. لا يمكن توزيعها.",
    "B:Muy bien. ¿Cuántas familias reciben ayuda cada semana?|حسنًا جدًّا. كم أسرة تتلقّى المساعدة كلّ أسبوع؟",
    "A:Unas ciento cincuenta. Por eso cada voluntario es tan importante.|نحو مئة وخمسين. لذلك فإنّ كلّ متطوّع مهمّ جدًّا.",
    "B:Pues aquí estoy. Si necesitáis ayuda los sábados, también puedo venir.|إذن ها أنا ذا. وإن احتجتم إلى مساعدة أيام السبت فبإمكاني المجيء أيضًا."
  ] },

  { id: "cv47", lv: "B2", ic: "📧", t: "Llamada de seguimiento tras una entrevista", tar: "مكالمة متابعة بعد مقابلة عمل", roles: ["مسؤول التوظيف", "المرشّحة"], d: [
    "A:Recursos Humanos, buenos días. Le habla Sergio.|الموارد البشرية، صباح الخير. معكِ سيرخيو.",
    "B:Buenos días, Sergio. Soy Amina El Idrissi. Hice una entrevista con ustedes el martes pasado para el puesto de analista de datos.|صباح الخير يا سيرخيو. أنا أمينة الإدريسي. أجريتُ معكم مقابلة يوم الثلاثاء الماضي لوظيفة محلّلة بيانات.",
    "A:Ah, sí, la recuerdo. ¿En qué puedo ayudarla?|آه نعم، أتذكّرك. كيف يمكنني مساعدتك؟",
    "B:Me dijeron que tendría noticias en una semana, y quería saber si ya hay alguna decisión.|قيل لي إنّني سأتلقّى خبرًا خلال أسبوع، وأردتُ أن أعرف إن كان هناك قرار بعد.",
    "A:Todavía no. Estamos terminando de entrevistar a los últimos candidatos, así que el proceso se ha retrasado un poco.|ليس بعد. نحن ننهي مقابلة آخر المرشّحين، لذلك تأخّرت العملية قليلًا.",
    "B:Lo entiendo perfectamente. ¿Hay alguna información adicional que pueda enviarles para completar mi candidatura?|أتفهّم ذلك تمامًا. هل هناك معلومات إضافية يمكنني إرسالها لاستكمال ترشّحي؟",
    "A:Pues, de hecho, el equipo técnico mencionó que le gustaría ver algún ejemplo de los paneles que ha diseñado.|في الواقع، ذكر الفريق التقني أنّه يودّ رؤية مثال على لوحات المعلومات التي صمّمتِها.",
    "B:Por supuesto. Puedo enviarles hoy mismo un enlace a mi portafolio, con dos proyectos sin datos personales.|بالطبع. يمكنني أن أرسل إليكم اليوم نفسه رابطًا إلى ملفّ أعمالي، فيه مشروعان بعد حجب البيانات الشخصية.",
    "A:Estupendo. Envíelo a la dirección de correo que le dimos y lo haré llegar al responsable.|ممتاز. أرسليه إلى البريد الإلكتروني الذي أعطيناكِ إيّاه، وسأوصله إلى المسؤول.",
    "B:Muchas gracias. ¿Cuándo calculan que tomarán una decisión?|شكرًا جزيلًا. متى تتوقّعون أن تتّخذوا القرار؟",
    "A:Si todo va bien, a finales de la semana que viene. La llamaremos en cualquier caso.|إن سار كلّ شيء على ما يرام، ففي نهاية الأسبوع القادم. وسنتّصل بكِ في جميع الأحوال.",
    "B:Perfecto. Le agradezco mucho su tiempo y quedo a su disposición.|ممتاز. أشكرك كثيرًا على وقتك، وأنا رهن إشارتكم."
  ] },

  { id: "cv48", lv: "B1", ic: "🎓", t: "Información en la universidad", tar: "الاستفسار في الجامعة", roles: ["موظّفة الاستعلامات", "الطالب"], d: [
    "A:Buenos días, oficina de información al estudiante. ¿Qué necesita?|صباح الخير، مكتب استعلامات الطلّاب. ماذا تحتاج؟",
    "B:Buenos días. Estoy interesado en el máster de Ingeniería Informática. ¿Cuáles son los requisitos?|صباح الخير. أنا مهتمّ بماجستير هندسة الحاسوب. ما الشروط المطلوبة؟",
    "A:Necesita un título de grado en informática o en un área relacionada, y un nivel B2 de español.|تحتاج إلى شهادة بكالوريوس في الحاسوب أو في مجال قريب منه، ومستوى B2 في الإسبانية.",
    "B:Mi título es de una universidad de Jordania. ¿Tengo que homologarlo?|شهادتي من جامعة في الأردن. هل يجب أن أعادلها؟",
    "A:Para el máster no siempre hace falta; la universidad revisa su título durante la admisión.|للماجستير لا يلزم ذلك دائمًا؛ فالجامعة تراجع شهادتك أثناء القبول.",
    "B:Perfecto. ¿Cuándo es el plazo de preinscripción?|ممتاز. متى فترة التقديم؟",
    "A:Está abierto del uno de marzo al treinta de abril. Todo se hace en línea.|إنّها مفتوحة من الأوّل من مارس إلى الثلاثين من أبريل. ويتمّ كلّ شيء عبر الإنترنت.",
    "B:¿Y cuánto cuesta la matrícula aproximadamente?|وكم تبلغ رسوم التسجيل تقريبًا؟",
    "A:Depende del número de créditos, pero ronda los dos mil euros al año. También hay becas.|يعتمد ذلك على عدد الساعات المعتمدة، لكنّها تقارب ألفي يورو في السنة. وهناك منح أيضًا.",
    "B:¿Las becas son también para estudiantes extranjeros?|هل المنح متاحة أيضًا للطلّاب الأجانب؟",
    "A:Algunas sí. Le doy este folleto con toda la información y la página web.|بعضها نعم. أعطيك هذا الكتيّب، وفيه كلّ المعلومات وعنوان الموقع الإلكتروني.",
    "B:Muchas gracias. Ha sido muy amable.|شكرًا جزيلًا. لقد كنتِ لطيفة جدًّا."
  ] },

  { id: "cv49", lv: "A2", ic: "🚙", t: "Alquilar un coche", tar: "استئجار سيارة", roles: ["موظّف الشركة", "الزبونة"], d: [
    "A:Buenos días. ¿Tiene una reserva?|صباح الخير. هل لديكِ حجز؟",
    "B:Sí, a nombre de Nadia Benali. Un coche pequeño para tres días.|نعم، باسم نادية بنعلي. سيارة صغيرة لثلاثة أيام.",
    "A:Aquí está. ¿Me deja su carné de conducir y su pasaporte?|ها هو. هل تعطينني رخصة القيادة وجواز السفر؟",
    "B:Claro, aquí los tiene. ¿El seguro está incluido?|بالطبع، تفضّل. هل التأمين مشمول؟",
    "A:El seguro básico, sí. El seguro a todo riesgo cuesta diez euros más al día.|التأمين الأساسي نعم. أمّا التأمين الشامل فيكلّف عشرة يورو إضافية في اليوم.",
    "B:Prefiero el básico, gracias. ¿Cómo devuelvo el coche?|أفضّل الأساسي، شكرًا. كيف أُعيد السيارة؟",
    "A:Con el depósito lleno, aquí mismo, el viernes antes de las seis.|بخزّان وقود ممتلئ، هنا نفسه، يوم الجمعة قبل السادسة.",
    "B:De acuerdo. ¿Tiene GPS?|حسنًا. هل فيها جهاز ملاحة؟",
    "A:Sí, y también puede conectar su móvil. Necesito una tarjeta para la fianza.|نعم، ويمكنكِ أيضًا توصيل هاتفكِ. أحتاج إلى بطاقة لمبلغ التأمين المسترَدّ.",
    "B:Aquí tiene. ¿Dónde está el coche?|تفضّل. أين السيارة؟",
    "A:En el aparcamiento, plaza número catorce. Estas son las llaves. ¡Buen viaje!|في الموقف، المكان رقم أربعة عشر. هذه هي المفاتيح. رحلة سعيدة!",
    "B:¡Muchas gracias! Hasta el viernes.|شكرًا جزيلًا! إلى يوم الجمعة."
  ] },

  { id: "cv50", lv: "A2", ic: "⚽", t: "Hablar de fútbol", tar: "حديث عن كرة القدم", roles: ["سامي", "خافي"], d: [
    "A:Javi, ¿viste el partido de anoche?|يا خافي، هل شاهدتَ مباراة البارحة؟",
    "B:¡Claro! ¡Qué partidazo! Ganamos tres a dos en el último minuto.|طبعًا! يا لها من مباراة رائعة! فزنا ثلاثة مقابل اثنين في الدقيقة الأخيرة.",
    "A:Yo solo vi la segunda parte. ¿Quién marcó el primer gol?|أنا شاهدتُ الشوط الثاني فقط. من سجّل الهدف الأوّل؟",
    "B:El delantero nuevo, de cabeza. Fue un gol precioso.|المهاجم الجديد، برأسه. كان هدفًا جميلًا.",
    "A:Me gusta mucho ese jugador. Corre muchísimo y nunca se rinde.|أحبّ ذلك اللاعب كثيرًا. يركض كثيرًا جدًّا ولا يستسلم أبدًا.",
    "B:Sí, pero el portero también jugó muy bien. Paró un penalti.|نعم، لكنّ الحارس أيضًا لعب جيّدًا جدًّا. صدّ ركلة جزاء.",
    "A:¿Y el árbitro? Mi hermano dice que fue muy malo.|والحَكَم؟ أخي يقول إنّه كان سيّئًا جدًّا.",
    "B:Bueno, se equivocó un par de veces, pero es un trabajo difícil.|حسنًا، أخطأ مرّتين، لكنّه عمل صعب.",
    "A:Es verdad. Oye, ¿tú juegas al fútbol?|صحيح. اسمع، هل تلعب كرة القدم؟",
    "B:Sí, los domingos con unos amigos en el polideportivo. ¿Quieres venir?|نعم، أيام الأحد مع بعض الأصدقاء في المجمّع الرياضي. هل تريد أن تأتي؟",
    "A:¡Me encantaría! Pero yo prefiero jugar de portero.|يسعدني ذلك كثيرًا! لكنّني أفضّل أن ألعب حارسًا للمرمى.",
    "B:¡Perfecto, nos falta uno! Te espero el domingo a las diez.|ممتاز، ينقصنا واحد! أنتظرك يوم الأحد في العاشرة."
  ] },

  { id: "cv51", lv: "A1", ic: "🍽️", t: "La cena en familia", tar: "العشاء مع العائلة", roles: ["الأب", "الابنة"], d: [
    "A:¡La cena está lista! ¿Dónde estáis todos?|العشاء جاهز! أين أنتم جميعًا؟",
    "B:¡Ya voy, papá! Me lavo las manos.|أنا قادمة يا أبي! سأغسل يديّ.",
    "A:Muy bien. Hoy hay sopa, pollo con arroz y fruta.|جيّد جدًّا. اليوم عندنا حساء ودجاج بالأرزّ وفاكهة.",
    "B:¡Qué bien! Me gusta mucho el pollo.|رائع! أحبّ الدجاج كثيرًا.",
    "A:Primero decimos «Bismillah» y comemos.|أوّلًا نقول «بسم الله» ثمّ نأكل.",
    "B:Bismillah. Papá, ¿me pasas el pan, por favor?|بسم الله. أبي، هل تناولني الخبز من فضلك؟",
    "A:Toma. ¿Qué tal hoy en el colegio?|خذي. كيف كان يومكِ في المدرسة؟",
    "B:Muy bien. Tengo una amiga nueva. Se llama Lucía.|جيّد جدًّا. لديّ صديقة جديدة. اسمها لوسيا.",
    "A:¡Qué bonito! ¿Quieres más arroz?|ما أجمل ذلك! هل تريدين مزيدًا من الأرزّ؟",
    "B:No, gracias. Ya estoy llena. ¡Alhamdulillah!|لا، شكرًا. لقد شبعت. الحمد لله!",
    "A:Ahora todos ayudamos a recoger la mesa.|والآن نساعد جميعًا في رفع الأطباق عن المائدة.",
    "B:¡Vale! Yo llevo los vasos a la cocina.|حسنًا! أنا آخذ الأكواب إلى المطبخ."
  ] },

  { id: "cv52", lv: "B1", ic: "💻", t: "Llamada al soporte técnico", tar: "الاتصال بالدعم الفنّي", roles: ["فنّي الدعم", "الموظّفة"], d: [
    "A:Soporte técnico, le atiende Pablo. ¿Cuál es el problema?|الدعم الفنّي، معكِ بابلو. ما المشكلة؟",
    "B:Hola, Pablo. Soy Huda, de contabilidad. No puedo entrar en mi cuenta del ordenador.|مرحبًا يا بابلو. أنا هدى من قسم المحاسبة. لا أستطيع الدخول إلى حسابي في الحاسوب.",
    "A:¿Le aparece algún mensaje de error?|هل تظهر لكِ رسالة خطأ؟",
    "B:Sí, dice que mi cuenta está bloqueada. Creo que me equivoqué con la contraseña varias veces.|نعم، تقول إنّ حسابي مقفل. أظنّ أنّني أخطأتُ في كلمة المرور عدّة مرّات.",
    "A:Es lo más habitual. Para confirmar su identidad, ¿me dice su número de empleada?|هذا هو الأكثر شيوعًا. للتحقّق من هويّتكِ، هل تخبرينني برقمكِ الوظيفي؟",
    "B:Es el tres, uno, ocho, cero, cinco.|إنّه ثلاثة، واحد، ثمانية، صفر، خمسة.",
    "A:Gracias. Ya he desbloqueado la cuenta. Le voy a enviar una contraseña temporal al móvil.|شكرًا. لقد فتحتُ الحساب. سأرسل إلى هاتفكِ كلمة مرور مؤقّتة.",
    "B:Ya me ha llegado. ¿Tengo que cambiarla?|وصلتني. هل يجب أن أغيّرها؟",
    "A:Sí, el sistema se lo pedirá al entrar. Use al menos doce caracteres, con números y símbolos.|نعم، سيطلب منكِ النظام ذلك عند الدخول. استخدمي اثني عشر حرفًا على الأقلّ مع أرقام ورموز.",
    "B:Vale, ya está. ¡Funciona! ¿Puedo guardarla en el navegador?|حسنًا، تمّ. إنّه يعمل! هل يمكنني حفظها في المتصفّح؟",
    "A:Mejor no. Le recomiendo usar el gestor de contraseñas de la empresa. Y nunca la comparta con nadie.|الأفضل لا. أنصحكِ باستخدام مدير كلمات المرور الخاصّ بالشركة. ولا تشاركيها مع أحد أبدًا.",
    "B:Entendido. Muchas gracias por la rapidez.|مفهوم. شكرًا جزيلًا على السرعة."
  ] },

  { id: "cv53", lv: "A2", ic: "🏛️", t: "Una visita guiada por Córdoba", tar: "جولة سياحية في قرطبة", roles: ["المرشدة", "السائح"], d: [
    "A:¡Bienvenidos a Córdoba! Me llamo Rocío y hoy soy su guía.|مرحبًا بكم في قرطبة! اسمي روسيو وأنا مرشدتكم اليوم.",
    "B:Encantado. ¿Cuánto dura la visita?|تشرّفت. كم تستغرق الجولة؟",
    "A:Unas tres horas. Primero vamos a ver el puente romano.|نحو ثلاث ساعات. سنرى أوّلًا الجسر الروماني.",
    "B:¡Qué antiguo parece! ¿De qué siglo es?|يبدو قديمًا جدًّا! من أيّ قرن هو؟",
    "A:Es del siglo primero, pero lo han reconstruido muchas veces.|إنّه من القرن الأوّل، لكنّه أُعيد بناؤه مرّات كثيرة.",
    "B:¿Y después adónde vamos?|وبعد ذلك إلى أين نذهب؟",
    "A:A la Mezquita-Catedral. Tiene más de ochocientas columnas.|إلى جامع قرطبة (المسجد-الكاتدرائية). فيه أكثر من ثمانمئة عمود.",
    "B:He visto fotos de los arcos rojos y blancos. ¡Son preciosos!|رأيتُ صور الأقواس الحمراء والبيضاء. إنّها رائعة!",
    "A:Sí, son muy famosos. Después vamos a pasear por la judería.|نعم، إنّها مشهورة جدًّا. بعدها سنتجوّل في الحيّ اليهودي القديم.",
    "B:¿Hay tiempo para comer?|هل هناك وقت للأكل؟",
    "A:Sí, a las dos paramos una hora. Hay restaurantes con comida halal cerca.|نعم، في الثانية نتوقّف ساعة. هناك مطاعم قريبة تقدّم طعامًا حلالًا.",
    "B:¡Perfecto! Muchas gracias, Rocío.|ممتاز! شكرًا جزيلًا يا روسيو."
  ] },

  { id: "cv54", lv: "B2", ic: "🙏", t: "Pedir perdón a un amigo", tar: "الاعتذار إلى صديق", roles: ["عمر", "صديقه ماركوس"], d: [
    "A:Marcos, ¿tienes un minuto? Quería hablar contigo de lo del sábado.|ماركوس، هل لديك دقيقة؟ أردتُ أن أحدّثك عمّا جرى يوم السبت.",
    "B:Si es por la mudanza... sí, la verdad es que me sentó mal.|إن كان الأمر يتعلّق بالانتقال إلى البيت الجديد... نعم، في الحقيقة أزعجني ذلك.",
    "A:Lo sé, y tienes toda la razón. Te prometí que te ayudaría y no aparecí ni te avisé.|أعرف، ومعك كلّ الحقّ. وعدتُك بأن أساعدك، فلم أحضر ولم أُعلمك.",
    "B:Te estuvimos esperando toda la mañana. Al final tuve que pedir ayuda a mi cuñado.|ظللنا ننتظرك طوال الصباح. وفي النهاية اضطررتُ إلى طلب المساعدة من صهري.",
    "A:No tengo excusa. Me quedé dormido y luego me dio vergüenza llamarte.|ليس لي عذر. غلبني النوم، ثمّ استحييتُ أن أتّصل بك.",
    "B:Hombre, un mensaje habría bastado. Lo que más me molestó fue el silencio.|يا رجل، كانت رسالة واحدة تكفي. أكثر ما أزعجني هو الصمت.",
    "A:Lo entiendo perfectamente. Te pido perdón de corazón. Cumplir la palabra es importante para mí, y te fallé.|أفهم ذلك تمامًا. أعتذر إليك من قلبي. الوفاء بالوعد مهمّ عندي، وقد خذلتُك.",
    "B:Bueno, valoro que me lo digas a la cara. No todo el mundo lo hace.|حسنًا، أقدّر أنّك تقول لي ذلك وجهًا لوجه. ليس كلّ الناس يفعلون ذلك.",
    "A:¿Hay algo que pueda hacer para compensarte? ¿Te ayudo a montar los muebles?|هل هناك ما يمكنني فعله لأعوّضك؟ هل أساعدك في تركيب الأثاث؟",
    "B:Pues mira, todavía tengo el armario en cajas. Si vienes el jueves, estamos en paz.|في الواقع ما زالت الخزانة في صناديقها. إن جئتَ يوم الخميس فقد تصافينا.",
    "A:Allí estaré a las seis, y esta vez llego puntual. Te lo prometo.|سأكون هناك في السادسة، وهذه المرّة سأصل في الموعد. أعدك بذلك.",
    "B:Más te vale... ¡Es broma! Gracias, Omar. Me alegra que lo hayamos aclarado.|من الأفضل لك ذلك... أمزح! شكرًا يا عمر. يسعدني أنّنا أوضحنا الأمر."
  ] },

  { id: "cv55", lv: "A1", ic: "🗺️", t: "Indicar el camino a una turista", tar: "إرشاد سائحة إلى الطريق", roles: ["السائحة", "أنت"], d: [
    "A:Perdón, ¿habla inglés?|عذرًا، هل تتكلّم الإنجليزية؟",
    "B:Un poco. Pero hablo español. ¿Qué busca?|قليلًا. لكنّني أتكلّم الإسبانية. عمّ تبحثين؟",
    "A:Busco la estación de tren. ¿Está lejos?|أبحث عن محطّة القطار. هل هي بعيدة؟",
    "B:No, está cerca. A diez minutos a pie.|لا، إنّها قريبة. على بُعد عشر دقائق مشيًا.",
    "A:¿Por dónde voy?|من أيّ طريق أذهب؟",
    "B:Siga todo recto por esta calle.|استمرّي في السير مباشرةً في هذا الشارع.",
    "A:¿Todo recto? Vale.|مباشرةً؟ حسنًا.",
    "B:Sí. En el semáforo, gire a la derecha.|نعم. عند إشارة المرور، انعطفي يمينًا.",
    "A:¿Y después?|وبعد ذلك؟",
    "B:La estación está a la izquierda, al lado de un parque.|المحطّة على اليسار، بجانب حديقة.",
    "A:¡Muchas gracias! Es usted muy amable.|شكرًا جزيلًا! أنت لطيف جدًّا.",
    "B:De nada. ¡Buen viaje!|عفوًا. رحلة سعيدة!"
  ] },

  { id: "cv56", lv: "A2", ic: "🦷", t: "En el dentista", tar: "عند طبيب الأسنان", roles: ["طبيبة الأسنان", "المريض"], d: [
    "A:Buenos días. Siéntese, por favor. ¿Qué le pasa?|صباح الخير. اجلس من فضلك. ممّ تشكو؟",
    "B:Me duele mucho una muela desde hace tres días.|يؤلمني ضرس كثيرًا منذ ثلاثة أيام.",
    "A:¿Le duele más con el frío o con el calor?|هل يؤلمك أكثر مع البارد أم مع الساخن؟",
    "B:Con el frío. Cuando bebo agua fría, me duele muchísimo.|مع البارد. عندما أشرب ماءً باردًا يؤلمني كثيرًا جدًّا.",
    "A:Abra la boca, por favor... Sí, tiene una caries grande.|افتح فمك من فضلك... نعم، عندك تسوّس كبير.",
    "B:¿Me la tiene que sacar?|هل يجب أن تخلعيه؟",
    "A:No, no hace falta. Le voy a poner un empaste.|لا، لا داعي لذلك. سأضع لك حشوة.",
    "B:¿Me va a doler?|هل سيؤلمني ذلك؟",
    "A:No se preocupe. Le pongo anestesia y no va a sentir nada.|لا تقلق. سأعطيك مخدّرًا ولن تشعر بشيء.",
    "B:Vale. ¿Puedo comer después?|حسنًا. هل يمكنني الأكل بعد ذلك؟",
    "A:Espere dos horas. Y recuerde: cepíllese los dientes después de cada comida.|انتظر ساعتين. وتذكّر: نظّف أسنانك بالفرشاة بعد كلّ وجبة.",
    "B:Sí, doctora. ¡Gracias!|نعم يا دكتورة. شكرًا!"
  ] },

  { id: "cv57", lv: "B1", ic: "💌", t: "Una invitación de boda", tar: "دعوة إلى حفل زفاف", roles: ["أحمد", "زميله راؤول"], d: [
    "A:Raúl, tengo una buena noticia: ¡mi hermana se casa el mes que viene!|يا راؤول، عندي خبر سارّ: أختي ستتزوّج الشهر القادم!",
    "B:¡Enhorabuena! Dale mi felicitación a tu hermana.|مبارك! بلّغ أختك تهنئتي.",
    "A:Gracias. Y me gustaría invitarte a la celebración, con tu familia.|شكرًا. وأودّ أن أدعوك إلى الحفل مع عائلتك.",
    "B:¡Qué detalle! Será un honor. ¿Cuándo y dónde es?|يا له من لطف! سيكون شرفًا لي. متى وأين؟",
    "A:El sábado veinte, a las siete de la tarde, en un salón de celebraciones cerca del río. Aquí tienes la invitación.|يوم السبت العشرين، في السابعة مساءً، في قاعة احتفالات قرب النهر. تفضّل بطاقة الدعوة.",
    "B:Gracias. Perdona la pregunta, pero nunca he ido a una boda musulmana. ¿Cómo es?|شكرًا. اعذرني على السؤال، لكنّني لم أحضر زفافًا إسلاميًّا من قبل. كيف يكون؟",
    "A:No te preocupes. Es una cena con la familia y los amigos. El contrato matrimonial se firma antes, en la mezquita.|لا تقلق. إنّه عشاء مع الأهل والأصدقاء. أمّا عقد الزواج فيُعقَد قبل ذلك في المسجد.",
    "B:¿Hay que llevar algo especial? ¿Un regalo, ropa formal...?|هل يجب إحضار شيء خاصّ؟ هديّة، ملابس رسمية...؟",
    "A:Ropa elegante, como en cualquier boda. Y el regalo no es obligatorio; lo importante es que vengáis.|ملابس أنيقة كما في أيّ زفاف. والهديّة ليست إلزامية؛ المهمّ أن تأتوا.",
    "B:¿Pueden venir los niños?|هل يمكن أن يأتي الأطفال؟",
    "A:¡Por supuesto! Habrá muchos niños. Mi madre está preparando dulces para todos.|بالطبع! سيكون هناك أطفال كثيرون. أمّي تُعِدّ الحلويات للجميع.",
    "B:Entonces allí estaremos. Te confirmo el número de personas esta semana.|إذن سنكون هناك. سأؤكّد لك عدد الأشخاص هذا الأسبوع."
  ] },

  { id: "cv58", lv: "B2", ic: "🧭", t: "Planear un viaje en familia", tar: "التخطيط لرحلة عائلية", roles: ["سلمى", "زوجها كريم"], d: [
    "A:Karim, ¿has pensado adónde podríamos ir en las vacaciones de primavera?|كريم، هل فكّرتَ إلى أين يمكن أن نذهب في عطلة الربيع؟",
    "B:Estaba pensando en Granada. Los niños estudian al-Ándalus en el colegio y les vendría bien verlo en persona.|كنت أفكّر في غرناطة. الأولاد يدرسون الأندلس في المدرسة، وسيفيدهم أن يروها بأعينهم.",
    "A:Me parece genial. ¿Vamos en coche o en tren?|تبدو فكرة رائعة. هل نذهب بالسيارة أم بالقطار؟",
    "B:En tren es más cómodo, pero en coche podríamos parar en Córdoba de camino.|القطار أكثر راحة، لكن بالسيارة يمكننا التوقّف في قرطبة في الطريق.",
    "A:Buena idea. Lo que sí deberíamos reservar ya son las entradas de la Alhambra; se agotan con semanas de antelación.|فكرة جيّدة. لكن ما ينبغي أن نحجزه الآن هو تذاكر قصر الحمراء؛ فهي تنفد قبل أسابيع.",
    "B:Tienes razón. Esta noche miro la web oficial. ¿Y el alojamiento?|معكِ حقّ. سأتصفّح الموقع الرسمي الليلة. والإقامة؟",
    "A:Prefiero un apartamento con cocina; así podemos preparar el desayuno y algunas cenas.|أفضّل شقّة فيها مطبخ؛ فبذلك نستطيع إعداد الفطور وبعض وجبات العشاء.",
    "B:De acuerdo. Y conviene que esté cerca de alguna mezquita o que tengamos sitio para rezar con tranquilidad.|موافق. ومن الأفضل أن تكون قريبة من مسجد، أو أن يكون لدينا مكان نصلّي فيه بهدوء.",
    "A:En el Albaicín hay una mezquita bastante conocida. Además, he visto que hay varios restaurantes halal por la zona.|في حيّ البيّازين مسجد معروف إلى حدّ كبير. كما رأيتُ أنّ في المنطقة عدّة مطاعم حلال.",
    "B:Perfecto. ¿Cuánto calculas que nos costará en total?|ممتاز. كم تقدّرين أن تكلّفنا الرحلة إجمالًا؟",
    "A:Si no nos pasamos con los extras, unos ochocientos euros para los cinco días.|إن لم نبالغ في الكماليات، فنحو ثمانمئة يورو للأيام الخمسة.",
    "B:Es razonable. Hagamos una lista de tareas y repartámoslas: tú el alojamiento y yo las entradas.|هذا معقول. لنُعِدّ قائمة بالمهامّ ونتقاسمها: أنتِ الإقامة وأنا التذاكر."
  ] },

  { id: "cv59", lv: "C1", ic: "📚", t: "Hablar de libros", tar: "حديث عن الكتب", roles: ["لينا", "صديقتها كلارا"], d: [
    "A:¿Qué estás leyendo últimamente, Clara? Siempre te veo con un libro bajo el brazo.|ماذا تقرئين مؤخّرًا يا كلارا؟ أراكِ دائمًا وتحت ذراعكِ كتاب.",
    "B:Estoy releyendo el Quijote. La primera vez lo dejé a medias, pero ahora disfruto muchísimo de su humor.|أعيد قراءة «دون كيخوته». في المرّة الأولى تركتُه في منتصفه، أمّا الآن فأستمتع كثيرًا بفكاهته.",
    "A:¡A mí me pasó lo mismo! Hay que leerlo sin prisa, saboreando cada capítulo.|حدث لي الشيء نفسه! يجب أن يُقرأ على مهل، مع تذوّق كلّ فصل.",
    "B:¿Y tú? ¿Sigues con los ensayos de historia?|وأنتِ؟ هل ما زلتِ مع الدراسات التاريخية؟",
    "A:Sí, ahora leo uno sobre la transmisión del saber en al-Ándalus. Explica cómo las traducciones de Toledo hicieron llegar a Europa obras de medicina y astronomía.|نعم، أقرأ الآن دراسة عن انتقال المعرفة في الأندلس. تشرح كيف أوصلت ترجمات طليطلة إلى أوروبا مؤلّفات في الطبّ والفلك.",
    "B:Suena apasionante, aunque me imagino que será bastante denso.|يبدو ذلك شيّقًا، وإن كنتُ أتخيّل أنّه ثقيل بعض الشيء.",
    "A:Tiene pasajes áridos, no te lo niego, pero el autor sabe combinar las anécdotas con el rigor académico.|فيه مقاطع جافّة، لا أنكر ذلك، لكنّ المؤلّف يجيد المزج بين الطرائف والدقّة الأكاديمية.",
    "B:Eso es lo que distingue a un buen divulgador. ¿Lees en papel o en formato digital?|هذا ما يميّز الكاتب البارع في تبسيط العلوم. هل تقرئين ورقيًّا أم رقميًّا؟",
    "A:En papel, sin duda. Necesito subrayar, escribir en los márgenes y volver atrás cuando algo se me escapa.|ورقيًّا بلا شكّ. أحتاج إلى أن أضع خطوطًا تحت الجمل، وأكتب في الهوامش، وأعود إلى الوراء حين يفوتني شيء.",
    "B:Yo me he pasado al libro electrónico por comodidad, pero reconozco que retengo menos lo que leo.|أنا انتقلتُ إلى الكتاب الإلكتروني طلبًا للراحة، لكنّني أعترف بأنّني أحتفظ في ذاكرتي بأقلّ ممّا أقرأ.",
    "A:¿Y si montamos un pequeño club de lectura? Un libro al mes y lo comentamos con un té.|ما رأيكِ أن ننشئ نادي قراءة صغيرًا؟ كتاب كلّ شهر نناقشه على كوب شاي.",
    "B:¡Me apunto! Pero con una condición: que alternemos novela y ensayo, para que ninguna de las dos se aburra.|أنا معكِ! لكن بشرط: أن نتناوب بين الرواية والدراسة، كي لا تملّ أيٌّ منّا."
  ] },

  /* ===== حوارات دعوية ===== */

  { id: "cv60", lv: "B1", ic: "🥤", t: "«¿Por qué no bebes alcohol?»", tar: "«لماذا لا تشرب الكحول؟»", roles: ["الزميل", "الداعية"], d: [
    "A:Hassan, el viernes vamos a celebrar el ascenso de Luis. ¿Te apuntas?|حسن، يوم الجمعة سنحتفل بترقية لويس. هل تنضمّ إلينا؟",
    "B:¡Qué buena noticia! Claro que quiero felicitarle. ¿Dónde será?|يا له من خبر جميل! بالطبع أريد أن أهنّئه. أين سيكون الاحتفال؟",
    "A:En el restaurante de la esquina. Te pido una cerveza, ¿no?|في المطعم الذي على الزاوية. أطلب لك جعة، أليس كذلك؟",
    "B:Gracias, pero yo no bebo alcohol. Para mí, un zumo de naranja.|شكرًا، لكنّني لا أشرب الكحول. أنا أريد عصير برتقال.",
    "A:¿Ni siquiera una copa de vino en ocasiones especiales?|ولا حتى كأس نبيذ في المناسبات الخاصّة؟",
    "B:Ni siquiera. En el islam el alcohol está prohibido, sea poco o mucho.|ولا حتى ذلك. الخمر محرّمة في الإسلام، قليلها وكثيرها.",
    "A:¿Y por qué? Si uno bebe con moderación, no pasa nada, ¿no?|ولماذا؟ إن شرب المرء باعتدال فلا بأس، أليس كذلك؟",
    "B:Entiendo tu punto de vista. Para nosotros es un mandato de Allah que aparece en el Corán (Corán 5:90). Y creo que tiene mucha sabiduría.|أفهم وجهة نظرك. بالنسبة إلينا هو أمر من الله ورد في القرآن (سورة المائدة: 90). وأرى أنّ فيه حكمة كبيرة.",
    "A:¿Qué sabiduría?|أيّ حكمة؟",
    "B:Piensa en los accidentes de tráfico, las peleas o los problemas familiares que empiezan con una copa de más. El islam prefiere cerrar esa puerta desde el principio.|فكّر في حوادث السير والشجارات والمشكلات الأسرية التي تبدأ بكأس زائدة. الإسلام يفضّل أن يغلق هذا الباب من البداية.",
    "A:Visto así, tiene sentido. Nunca lo había pensado.|إذا نظرنا إليه هكذا فهو منطقي. لم أفكّر في ذلك من قبل.",
    "B:Gracias por preguntar en lugar de suponer. Por cierto, ¿qué te parece si llevo unos dulces árabes a la oficina para felicitar a Luis?|شكرًا لأنّك سألت بدل أن تفترض. بالمناسبة، ما رأيك أن أُحضر بعض الحلويات العربية إلى المكتب لتهنئة لويس؟"
  ] },

  { id: "cv61", lv: "B1", ic: "🌙", t: "Ramadán en época de exámenes", tar: "رمضان في موسم الامتحانات", roles: ["زميلة الدراسة", "الداعية"], d: [
    "A:Yasmín, ¿quieres un poco de mi bocadillo? Llevamos tres horas en la biblioteca.|ياسمين، هل تريدين قليلًا من شطيرتي؟ لنا ثلاث ساعات في المكتبة.",
    "B:Muchas gracias, Irene, pero estoy ayunando. Ramadán empezó ayer.|شكرًا جزيلًا يا إيرين، لكنّني صائمة. بدأ رمضان أمس.",
    "A:¡Ay, perdona! No lo sabía. ¿Te molesta que coma delante de ti?|آه، سامحيني! لم أكن أعلم. هل يزعجك أن آكل أمامك؟",
    "B:Para nada, come tranquila. Te agradezco mucho la delicadeza.|أبدًا، كُلي براحتك. أقدّر كثيرًا لطفكِ.",
    "A:¿Y puedes estudiar bien sin comer ni beber? Yo sin café no soy nadie.|وهل تستطيعين الدراسة جيّدًا دون أكل أو شرب؟ أنا بلا قهوة لا أساوي شيئًا.",
    "B:Los primeros días cuesta un poco, pero luego el cuerpo se acostumbra. Me levanto antes del alba para comer algo; se llama suhur.|الأيام الأولى صعبة قليلًا، لكنّ الجسم يعتاد بعد ذلك. أستيقظ قبل الفجر لآكل شيئًا؛ ويسمّى السحور.",
    "A:¿Y si te pones enferma justo en exámenes?|وإن مرضتِ في وقت الامتحانات بالذات؟",
    "B:El islam es una religión de facilidad. Quien está enfermo o de viaje puede no ayunar y recuperar esos días después (Corán 2:184).|الإسلام دين يُسر. فمن كان مريضًا أو على سفر فله أن يُفطر ويقضي تلك الأيام لاحقًا (سورة البقرة: 184).",
    "A:No sabía que había excepciones. ¿Y los niños también ayunan?|لم أكن أعلم أنّ هناك استثناءات. وهل يصوم الأطفال أيضًا؟",
    "B:No es obligatorio para ellos, aunque muchos lo intentan unas horas para ir practicando, como yo de pequeña.|ليس واجبًا عليهم، وإن كان كثير منهم يحاولون بضع ساعات ليتدرّبوا، كما كنت أفعل في صغري.",
    "A:Me parece admirable. ¿Puedo hacer algo para ayudarte estos días?|يبدو لي ذلك جديرًا بالإعجاب. هل أستطيع أن أفعل شيئًا لمساعدتك في هذه الأيام؟",
    "B:Pues sí: ¿qué tal si estudiamos por las mañanas, cuando tengo más energía? Y el último día de exámenes te invito a cenar en casa a la hora del iftar.|نعم: ما رأيكِ أن ندرس في الصباح حين تكون طاقتي أكبر؟ وفي آخر يوم من الامتحانات أدعوكِ إلى العشاء في بيتنا وقت الإفطار."
  ] },

  { id: "cv62", lv: "B2", ic: "🌹", t: "María y Jesús en el islam", tar: "مريم وعيسى عليهما السلام في الإسلام", roles: ["الصديقة الكاثوليكية", "الداعية"], d: [
    "A:Nour, el otro día te oí hablar de María, la madre de Jesús. ¿Los musulmanes también la honráis?|نور، سمعتُكِ قبل أيام تتحدّثين عن مريم أمّ عيسى. هل تكرّمونها أنتم المسلمون أيضًا؟",
    "B:Sí, muchísimo. De hecho, hay una sura entera del Corán que lleva su nombre: la sura de María (Corán 19).|نعم، كثيرًا جدًّا. بل إنّ في القرآن سورة كاملة تحمل اسمها: سورة مريم (السورة 19).",
    "A:¡No tenía ni idea! Yo soy católica y le tengo mucha devoción.|لم تكن لديّ أيّ فكرة! أنا كاثوليكية وأكنّ لها إجلالًا كبيرًا.",
    "B:Lo sé, y lo respeto. El Corán la presenta como una mujer pura, a la que Allah eligió y honró por encima de las demás mujeres (Corán 3:42).|أعرف ذلك وأحترمه. القرآن يقدّمها امرأةً طاهرة، اختارها الله وفضّلها على سائر النساء (سورة آل عمران: 42).",
    "A:¿Y qué dice el Corán de Jesús? ¿Lo consideráis hijo de Dios?|وماذا يقول القرآن عن عيسى؟ هل تعتبرونه ابن الله؟",
    "B:Te respondo con sinceridad y con respeto: para nosotros, Jesús es uno de los más grandes profetas, nacido milagrosamente sin padre, pero es siervo y mensajero de Allah, no Su hijo.|سأجيبكِ بصدق واحترام: عيسى عندنا من أعظم الأنبياء، وُلد بمعجزة من غير أب، لكنّه عبد الله ورسوله، لا ابنه.",
    "A:Justo ahí están nuestras diferencias.|هنا بالضبط تكمن خلافاتنا.",
    "B:Así es, y no quiero quitarle importancia. Pero me parece bonito que, al mismo tiempo, compartamos el amor por Jesús y por su madre.|هذا صحيح، ولا أريد أن أقلّل من أهمّيته. لكن يبدو لي جميلًا أنّنا في الوقت نفسه نشترك في محبّة عيسى وأمّه.",
    "A:¿Es verdad que el Corán habla de cuando Jesús era un bebé?|هل صحيح أنّ القرآن يتحدّث عن عيسى وهو رضيع؟",
    "B:Sí, cuenta que habló en la cuna para defender la inocencia de su madre (Corán 19:27-33). Si quieres, te paso esa sura en una traducción de QuranEnc.|نعم، يذكر أنّه تكلّم في المهد ليدافع عن براءة أمّه (سورة مريم: 27-33). إن أحببتِ أرسلتُ لكِ هذه السورة بترجمة من موقع QuranEnc.",
    "A:Sí, por favor. Me gustaría leerla con calma y comentarla contigo.|نعم من فضلك. أودّ أن أقرأها بهدوء وأناقشها معكِ.",
    "B:Cuando quieras. Y si te surge alguna pregunta que no sepa responder, la consultaré antes de decirte nada.|متى شئتِ. وإن خطر لكِ سؤال لا أعرف جوابه فسأسأل أهل العلم قبل أن أقول لكِ شيئًا."
  ] },

  { id: "cv63", lv: "B2", ic: "🌌", t: "«¿Por qué creer en Dios?»", tar: "«لماذا نؤمن بالله؟»", roles: ["الزميل الملحد", "الداعية"], d: [
    "A:Te voy a ser sincero, Ibrahim: yo no creo en Dios. Para mí, todo tiene una explicación científica.|سأكون صريحًا معك يا إبراهيم: أنا لا أؤمن بالله. بالنسبة إليّ، لكلّ شيء تفسير علمي.",
    "B:Gracias por tu sinceridad. Me interesa de verdad saber cómo llegaste a esa conclusión.|شكرًا على صراحتك. يهمّني حقًّا أن أعرف كيف وصلتَ إلى هذا الاستنتاج.",
    "A:Crecí en una familia religiosa, pero con los años empecé a tener dudas que nadie me respondía.|نشأتُ في أسرة متديّنة، لكن مع السنين بدأت تراودني شكوك لم يجبني عنها أحد.",
    "B:Te entiendo. Hacerse preguntas es sano; el Corán invita constantemente a reflexionar y a usar la razón.|أفهمك. طرح الأسئلة أمر صحّي؛ والقرآن يدعو باستمرار إلى التفكّر واستعمال العقل.",
    "A:Pero ¿qué razón hay para creer? La ciencia explica cómo funciona el universo.|لكن أيّ سبب يدعو إلى الإيمان؟ العلم يفسّر كيف يعمل الكون.",
    "B:Estoy de acuerdo en que la ciencia explica el «cómo». Pero queda otra pregunta: ¿por qué existe algo en lugar de nada?|أوافقك على أنّ العلم يفسّر «الكيف». لكن يبقى سؤال آخر: لماذا يوجد شيء بدلًا من لا شيء؟",
    "A:Quizá el universo simplemente existe, sin más.|ربّما الكون موجود فحسب، ولا شيء وراء ذلك.",
    "B:Es una posibilidad que muchos plantean. Yo lo veo así: todo lo que empieza a existir tiene una causa. El Corán plantea esta misma pregunta: si fuimos creados de la nada o si nos creamos a nosotros mismos (Corán 52:35).|هذا احتمال يطرحه كثيرون. أمّا أنا فأرى الأمر هكذا: كلّ ما بدأ وجوده فله سبب. والقرآن يطرح السؤال نفسه: هل وُجدنا من غير موجِد، أم أوجدنا أنفسنا؟ (سورة الطور: 35).",
    "A:Es un argumento interesante, aunque no me convence del todo.|إنّها حجّة مثيرة للاهتمام، وإن كانت لا تقنعني تمامًا.",
    "B:Lo respeto. No pretendo convencerte en una sola conversación. Solo te invito a pensarlo con calma y con el corazón abierto.|أحترم ذلك. لا أطمح إلى إقناعك في محادثة واحدة. أدعوك فقط إلى أن تفكّر فيه بهدوء وبقلب منفتح.",
    "A:Me parece justo. ¿Hay algo que pueda leer sin que sea un sermón?|يبدو ذلك منصفًا. هل هناك ما يمكنني قراءته دون أن يكون موعظة؟",
    "B:Sí. En IslamHouse hay libros breves en español sobre la existencia de Dios, con argumentos racionales. Te envío uno y, si quieres, lo comentamos otro día.|نعم. في موقع IslamHouse كتب قصيرة بالإسبانية عن وجود الله، بحجج عقلية. سأرسل لك واحدًا، وإن شئتَ ناقشناه يومًا آخر."
  ] },

  { id: "cv64", lv: "B2", ic: "🧭", t: "¿Para qué estamos aquí?", tar: "لماذا نحن هنا؟", roles: ["الزميلة المرهقة", "الداعية"], d: [
    "A:Salma, perdona que te moleste. Llevo semanas agotada y hoy me he preguntado para qué hago todo esto.|سلمى، اعذريني على الإزعاج. أنا منهكة منذ أسابيع، واليوم سألتُ نفسي: لماذا أفعل كلّ هذا؟",
    "B:No me molestas en absoluto. Siéntate, te preparo un té. ¿Qué te ha pasado?|لا تزعجينني أبدًا. اجلسي، سأُعِدّ لكِ شايًا. ماذا حدث لكِ؟",
    "A:Nada concreto. Trabajo, pago facturas, duermo y vuelta a empezar. Siento que me falta algo.|لا شيء محدّد. أعمل وأدفع الفواتير وأنام، ثمّ أبدأ من جديد. أشعر أنّ شيئًا ما ينقصني.",
    "B:Te escucho. Muchas personas sienten ese vacío, incluso cuando lo tienen todo.|أنا أصغي إليكِ. كثير من الناس يشعرون بهذا الفراغ حتى حين يملكون كلّ شيء.",
    "A:¿Y tú nunca te sientes así? Siempre te veo tan tranquila.|وأنتِ، ألا تشعرين بهذا أبدًا؟ أراكِ دائمًا هادئة جدًّا.",
    "B:Claro que tengo días malos, como todo el mundo. Pero me ayuda mucho saber para qué estoy aquí.|بالطبع لديّ أيام سيّئة مثل الجميع. لكن يساعدني كثيرًا أن أعرف لماذا أنا هنا.",
    "A:¿Y para qué estás aquí, según tú?|ولماذا أنتِ هنا في رأيكِ؟",
    "B:Creo que Allah nos creó para que le adoremos (Corán 51:56). Y adorarle no es solo rezar: también es trabajar con honradez, cuidar a los padres o sonreír a alguien.|أؤمن بأنّ الله خلقنا لنعبده (سورة الذاريات: 56). والعبادة ليست الصلاة فقط، بل هي أيضًا العمل بأمانة، والبرّ بالوالدين، والابتسامة في وجه الآخرين.",
    "A:Entonces, ¿hasta mi trabajo podría tener sentido?|إذن، حتى عملي يمكن أن يكون له معنى؟",
    "B:Exacto. Cuando haces las cosas con buena intención, buscando agradar a tu Creador, la rutina se convierte en algo valioso.|بالضبط. حين تؤدّين الأشياء بنيّة صالحة ابتغاء مرضاة خالقكِ، يصبح الروتين شيئًا ذا قيمة.",
    "A:Me gustaría entender eso mejor. Pero no quiero que me presiones, ¿vale?|أودّ أن أفهم هذا أكثر. لكن لا أريدكِ أن تضغطي عليّ، اتّفقنا؟",
    "B:Te lo prometo. Hablaremos solo cuando tú quieras. Y si un día te apetece leer algo breve, tengo un librito precioso de IslamHouse sobre el sentido de la vida.|أعدكِ بذلك. لن نتحدّث إلّا حين تريدين. وإن رغبتِ يومًا في قراءة شيء قصير، فعندي كتيّب جميل من IslamHouse عن معنى الحياة."
  ] },

  { id: "cv65", lv: "B2", ic: "🤍", t: "Acompañar a un amigo en el duelo", tar: "مواساة صديق فقد أباه", roles: ["الصديق", "الداعية"], d: [
    "A:Gracias por venir a casa, Mustafá. No esperaba verte hoy.|شكرًا على مجيئك إلى البيت يا مصطفى. لم أتوقّع أن أراك اليوم.",
    "B:Lo siento muchísimo, Andrés. Tu padre era un hombre muy bueno; siempre me saludaba con una sonrisa.|أنا آسف جدًّا يا أندريس. كان والدك رجلًا طيّبًا جدًّا؛ كان يحيّيني دائمًا بابتسامة.",
    "A:Todavía no me lo creo. Hace una semana estábamos hablando de sus vacaciones.|ما زلتُ لا أصدّق. قبل أسبوع كنّا نتحدّث عن عطلته.",
    "B:Es normal sentirse así. No hace falta que digas nada; estoy aquí para escucharte.|من الطبيعي أن تشعر هكذا. لا داعي لأن تقول شيئًا؛ أنا هنا لأصغي إليك.",
    "A:Lo peor son las noches. Me pregunto dónde está ahora, si sufre, si hay algo después...|أسوأ ما في الأمر الليالي. أتساءل أين هو الآن، وهل يتألّم، وهل هناك شيء بعد الموت...",
    "B:Son preguntas muy humanas. Yo no puedo hablar del destino de nadie; eso solo lo sabe Allah, que es el más justo y el más misericordioso.|إنّها أسئلة إنسانية جدًّا. أنا لا أستطيع أن أتكلّم عن مصير أحد؛ فذلك لا يعلمه إلّا الله، وهو أعدل العادلين وأرحم الراحمين.",
    "A:¿Y tú qué crees que hay después de la muerte?|وأنت، ماذا تعتقد أنّ هناك بعد الموت؟",
    "B:Creo que la muerte no es el final, sino el paso a otra vida, y que un día todos volveremos a nuestro Creador. Esa idea me da consuelo y esperanza.|أؤمن بأنّ الموت ليس النهاية، بل انتقال إلى حياة أخرى، وأنّنا جميعًا سنرجع يومًا إلى خالقنا. وهذه الفكرة تمنحني العزاء والأمل.",
    "A:Me gustaría creer algo así. Ahora mismo me siento perdido.|أتمنّى لو أؤمن بشيء كهذا. أشعر الآن بالضياع.",
    "B:Tómate tu tiempo; el dolor necesita su espacio. ¿Has comido algo hoy? Mi mujer ha preparado una sopa para tu familia.|خذ وقتك؛ فالحزن يحتاج إلى مساحته. هل أكلتَ شيئًا اليوم؟ زوجتي أعدّت حساءً لأسرتك.",
    "A:Sois muy amables. No sé cómo agradecéroslo.|أنتم لطفاء جدًّا. لا أعرف كيف أشكركم.",
    "B:No tienes nada que agradecer. Llámame cuando quieras, de día o de noche. Y cuando te sientas preparado, si quieres, hablamos de esas preguntas con calma.|لا داعي للشكر. اتّصل بي متى شئت، ليلًا أو نهارًا. وحين تشعر بأنّك مستعدّ، إن أردتَ، نتحدّث في تلك الأسئلة بهدوء."
  ] },

  { id: "cv66", lv: "B1", ic: "📰", t: "Después de ver las noticias", tar: "بعد مشاهدة الأخبار", roles: ["الجار", "الداعية"], d: [
    "A:Ali, ¿puedo preguntarte algo? Anoche vi en las noticias un atentado y decían que los autores eran musulmanes.|علي، هل أستطيع أن أسألك شيئًا؟ رأيتُ البارحة في الأخبار هجومًا إرهابيًّا، وكانوا يقولون إنّ منفّذيه مسلمون.",
    "B:Claro, pregunta. Antes que nada, lo siento mucho por las víctimas. Es algo terrible.|بالطبع، اسأل. قبل كلّ شيء، أنا حزين جدًّا على الضحايا. إنّه أمر فظيع.",
    "A:Lo que no entiendo es por qué alguien haría eso en nombre de una religión.|ما لا أفهمه هو لماذا يفعل أحدٌ ذلك باسم دين.",
    "B:Yo tampoco lo entiendo. El islam prohíbe matar a inocentes. El Corán enseña que matar a una persona inocente es como matar a toda la humanidad (Corán 5:32).|ولا أنا أفهمه. الإسلام يحرّم قتل الأبرياء. والقرآن يعلّم أنّ قتل نفس بريئة كقتل الناس جميعًا (سورة المائدة: 32).",
    "A:Entonces, ¿por qué se habla tanto de islam y violencia?|إذن، لماذا يكثر الحديث عن الإسلام والعنف؟",
    "B:Las malas noticias hacen más ruido. Pero hay casi dos mil millones de musulmanes que viven, trabajan y cuidan de sus familias en paz, como yo.|الأخبار السيّئة تُحدث ضجيجًا أكبر. لكن هناك قرابة ملياري مسلم يعيشون ويعملون ويرعون أسرهم بسلام، مثلي.",
    "A:Es verdad. Tú eres el vecino más amable del edificio.|صحيح. أنت ألطف جار في المبنى.",
    "B:¡Gracias! Intento serlo, porque el Profeta Muhammad insistió mucho en tratar bien al vecino.|شكرًا! أحاول أن أكون كذلك، لأنّ النبي محمدًا ﷺ أوصى كثيرًا بالإحسان إلى الجار.",
    "A:No lo sabía. Supongo que no debo juzgar a todos por lo que hacen unos pocos.|لم أكن أعلم ذلك. أظنّ أنّه لا ينبغي أن أحكم على الجميع بما يفعله قلّة.",
    "B:Te lo agradezco. Cada persona responde de sus propios actos; así lo enseña también el Corán (Corán 6:164).|أشكرك على ذلك. كلّ إنسان مسؤول عن أفعاله؛ وهذا ما يعلّمه القرآن أيضًا (سورة الأنعام: 164).",
    "A:Me ha gustado poder hablarlo contigo con tanta confianza.|أعجبني أن أستطيع الحديث معك في هذا بكلّ هذه الثقة.",
    "B:Y a mí. Cuando veas algo que te preocupe, pregúntame directamente. Es mucho mejor que quedarse con la duda.|وأنا كذلك. حين ترى شيئًا يقلقك، اسألني مباشرة. فذلك أفضل بكثير من أن تبقى في حيرة."
  ] },

  { id: "cv67", lv: "B2", ic: "🧕", t: "La mujer en el islam", tar: "المرأة في الإسلام", roles: ["الزميلة", "الداعية"], d: [
    "A:Zainab, ¿puedo ser directa contigo? Tengo la impresión de que en el islam la mujer está por debajo del hombre.|زينب، هل أستطيع أن أكون صريحة معكِ؟ لديّ انطباع بأنّ المرأة في الإسلام أدنى منزلةً من الرجل.",
    "B:Claro, y te agradezco que me lo preguntes a mí en lugar de quedarte con esa idea. ¿De dónde te viene esa impresión?|بالطبع، وأشكركِ لأنّكِ تسألينني بدل أن تبقي على هذه الفكرة. من أين جاءكِ هذا الانطباع؟",
    "A:Sobre todo de lo que veo en las noticias y de lo que ocurre en algunos países.|غالبًا ممّا أراه في الأخبار وممّا يحدث في بعض البلدان.",
    "B:Entiendo. Es importante distinguir entre lo que enseña el islam y las costumbres o los errores de algunas personas.|أفهم. من المهمّ التمييز بين ما يعلّمه الإسلام وبين العادات أو أخطاء بعض الناس.",
    "A:¿Y qué enseña el islam sobre la mujer?|وماذا يعلّم الإسلام عن المرأة؟",
    "B:Que hombres y mujeres son iguales ante Allah en dignidad y en la recompensa de sus obras; el Corán lo repite en varios lugares (Corán 33:35; 16:97).|أنّ الرجال والنساء سواء عند الله في الكرامة وفي جزاء أعمالهم؛ والقرآن يكرّر ذلك في مواضع عدّة (سورة الأحزاب: 35؛ سورة النحل: 97).",
    "A:Pero luego hay normas distintas para hombres y mujeres, ¿no?|لكن هناك بعد ذلك أحكام مختلفة للرجال والنساء، أليس كذلك؟",
    "B:Sí, hay algunas diferencias en ciertas responsabilidades, igual que el cuerpo y la naturaleza de cada uno son distintos. Pero diferencia no significa inferioridad.|نعم، هناك بعض الاختلافات في مسؤوليات معيّنة، كما أنّ جسد كلٍّ منهما وطبيعته مختلفان. لكنّ الاختلاف لا يعني الدونية.",
    "A:¿Por ejemplo? Me han dicho que la mujer hereda menos.|مثلًا؟ قيل لي إنّ المرأة ترث أقلّ.",
    "B:Ese tema tiene muchos detalles y, sinceramente, no los conozco bien. Prefiero consultarlo con alguien de conocimiento antes de darte una respuesta incompleta.|لهذا الموضوع تفاصيل كثيرة، وبصراحة لا أعرفها جيّدًا. أفضّل أن أسأل أحد أهل العلم قبل أن أعطيكِ إجابة ناقصة.",
    "A:Te agradezco la honestidad. Eso me da más confianza.|أقدّر صدقكِ. هذا يمنحني ثقة أكبر.",
    "B:Lo que sí sé es que la primera persona que creyó en el Profeta Muhammad fue su esposa Jadiya, una gran comerciante, y que él enseñó que la madre es quien más merece nuestro buen trato. Si quieres, te paso un libro de IslamHouse sobre este tema.|ما أعرفه يقينًا أنّ أوّل من آمن بالنبي محمد ﷺ زوجته خديجة رضي الله عنها، وكانت تاجرة كبيرة، وأنّه ﷺ علّمنا أنّ الأمّ أحقّ الناس بحسن الصحبة. وإن أحببتِ أرسلتُ لكِ كتابًا من IslamHouse عن هذا الموضوع."
  ] },

  { id: "cv68", lv: "B1", ic: "🕌", t: "Jornada de puertas abiertas en la mezquita", tar: "يوم مفتوح في المسجد", roles: ["الجارة", "الداعية"], d: [
    "A:¡Hola, Yusuf! He visto el cartel de la jornada de puertas abiertas y he venido con mi hijo.|مرحبًا يا يوسف! رأيتُ إعلان اليوم المفتوح، وجئتُ مع ابني.",
    "B:¡Qué alegría, Pilar! Bienvenidos los dos. ¿Queréis que os enseñe la mezquita?|يا للفرح يا بيلار! أهلًا بكما. هل تريدان أن أُريكما المسجد؟",
    "A:Sí, por favor. Lo primero que me llama la atención es que no hay imágenes ni estatuas.|نعم من فضلك. أوّل ما يلفت انتباهي أنّه لا توجد صور ولا تماثيل.",
    "B:Así es. En el islam adoramos solo a Allah, directamente, sin imágenes. Por eso la decoración es caligrafía y formas geométricas.|هذا صحيح. في الإسلام نعبد الله وحده مباشرة، دون صور. ولهذا تكون الزخرفة خطًّا عربيًّا وأشكالًا هندسية.",
    "A:¿Y qué es esa especie de escalera de madera?|وما ذاك الشيء الخشبي الذي يشبه الدرج؟",
    "B:Es el minbar. Desde ahí el imam da el sermón del viernes.|إنّه المنبر. من هناك يلقي الإمام خطبة الجمعة.",
    "A:¿El imam es como un sacerdote?|هل الإمام مثل الكاهن؟",
    "B:No exactamente. El imam dirige la oración y enseña, pero no es un intermediario entre la gente y Allah. Cada uno puede dirigirse a Allah directamente.|ليس تمامًا. الإمام يؤمّ الصلاة ويعلّم، لكنّه ليس وسيطًا بين الناس والله. يستطيع كلّ واحد أن يتوجّه إلى الله مباشرة.",
    "A:Y esa sala con grifos, ¿para qué es?|وتلك القاعة التي فيها صنابير، ما الغرض منها؟",
    "B:Es la sala de abluciones. Antes de rezar nos lavamos, porque nos presentamos ante Allah limpios.|إنّها قاعة الوضوء. قبل الصلاة نتوضّأ، لأنّنا نقف بين يدي الله ونحن أطهار.",
    "A:Mi hijo dice que le gusta el silencio que hay aquí.|ابني يقول إنّه يحبّ الهدوء الذي هنا.",
    "B:¡Qué bonito! Venid a la sala de al lado: hemos preparado té, dulces y libros gratuitos en español para quien quiera llevárselos.|ما أجمل ذلك! تعاليا إلى القاعة المجاورة: أعددنا شايًا وحلويات وكتبًا مجّانية بالإسبانية لمن يريد أن يأخذها."
  ] },

  { id: "cv69", lv: "B2", ic: "📖", t: "¿De dónde viene el Corán?", tar: "من أين جاء القرآن؟", roles: ["الطالب", "الداعية"], d: [
    "A:Abdullah, tengo curiosidad: ¿quién escribió el Corán? ¿Fue Muhammad?|عبد الله، عندي فضول: من كتب القرآن؟ هل هو محمد؟",
    "B:Es una pregunta muy buena. Los musulmanes creemos que el Corán es la palabra de Allah, revelada al Profeta Muhammad por medio del ángel Gabriel.|سؤال جيّد جدًّا. نحن المسلمين نؤمن بأنّ القرآن كلام الله، أوحاه إلى النبي محمد ﷺ بواسطة الملَك جبريل عليه السلام.",
    "A:¿Y cómo se reveló? ¿Todo de una vez?|وكيف نزل؟ دفعة واحدة؟",
    "B:No, poco a poco, durante unos veintitrés años, según los acontecimientos que vivían los musulmanes.|لا، بل نزل مفرّقًا على مدى ثلاث وعشرين سنة تقريبًا، بحسب الأحداث التي كان يعيشها المسلمون.",
    "A:Pero ¿cómo sabéis que no lo compuso él mismo?|لكن كيف تعرفون أنّه لم يؤلّفه بنفسه؟",
    "B:Hay varias razones que a mí me convencen. Una es que el Profeta no sabía leer ni escribir, y aun así trajo un texto de una elocuencia que los mejores poetas árabes no pudieron igualar.|هناك أسباب عدّة تقنعني. منها أنّ النبي ﷺ كان أمّيًّا لا يقرأ ولا يكتب، ومع ذلك جاء بنصّ بليغ عجز أفصح شعراء العرب عن مجاراته.",
    "A:¿Y no hubo nadie que intentara imitarlo?|ألم يحاول أحد تقليده؟",
    "B:El propio Corán lanza ese desafío: producir una sola sura semejante (Corán 2:23). Hay mucho escrito sobre ello; yo no soy experto en lingüística, pero te puedo recomendar fuentes serias.|القرآن نفسه يطرح هذا التحدّي: أن يأتوا بسورة واحدة مثله (سورة البقرة: 23). وقد كُتب في ذلك الكثير؛ لستُ خبيرًا في اللغة، لكن يمكنني أن أدلّك على مصادر جادّة.",
    "A:¿Y el texto ha cambiado con los siglos?|وهل تغيّر النصّ عبر القرون؟",
    "B:No. Se memorizó y se escribió desde la época del Profeta, y hoy millones de personas lo saben de memoria, letra por letra, igual en todo el mundo.|لا. فقد حُفظ وكُتب منذ عهد النبي ﷺ، واليوم يحفظه ملايين الناس عن ظهر قلب حرفًا حرفًا، بالنصّ نفسه في جميع أنحاء العالم.",
    "A:Eso no lo sabía. ¿Puedo leerlo en español?|هذا لم أكن أعرفه. هل يمكنني قراءته بالإسبانية؟",
    "B:Sí, aunque lo que leerás es una traducción de sus significados, porque el Corán como tal está en árabe. En QuranEnc.com tienes traducciones revisadas al español.|نعم، مع أنّ ما ستقرؤه ترجمة لمعانيه، لأنّ القرآن بلفظه عربيّ. وفي موقع QuranEnc.com تجد ترجمات إسبانية مراجَعة."
  ] },

  { id: "cv70", lv: "B2", ic: "⏳", t: "¿Qué pasa después de la muerte?", tar: "ماذا يحدث بعد الموت؟", roles: ["الصديق", "الداعية"], d: [
    "A:Hamza, el otro día en el hospital vi morir a un paciente. Desde entonces no dejo de pensar: ¿qué pasa después de la muerte?|حمزة، رأيتُ قبل أيام في المستشفى مريضًا يموت. ومنذ ذلك الحين لا أكفّ عن التفكير: ماذا يحدث بعد الموت؟",
    "B:Debió de ser muy duro. ¿Cómo estás tú?|لا بدّ أنّ ذلك كان صعبًا جدًّا. كيف حالك أنت؟",
    "A:Mejor, pero me ha removido mucho por dentro. ¿Qué cree el islam?|أفضل، لكنّه هزّني كثيرًا من الداخل. بماذا يؤمن الإسلام؟",
    "B:Creemos que el alma no desaparece. Después de la muerte hay una etapa de espera, la vida en la tumba, hasta el Día de la Resurrección.|نؤمن بأنّ الروح لا تفنى. بعد الموت هناك مرحلة انتظار هي حياة البرزخ في القبر، إلى يوم القيامة.",
    "A:¿Y qué pasará ese día?|وماذا سيحدث في ذلك اليوم؟",
    "B:Allah resucitará a todas las personas y cada uno verá sus obras, buenas y malas. Nadie cargará con las culpas de otro, y nadie será tratado injustamente.|سيبعث الله الناس جميعًا، وسيرى كلّ واحد أعماله خيرها وشرّها. لا يحمل أحدٌ ذنب غيره، ولا يُظلَم أحد.",
    "A:¿Y después? ¿Cielo e infierno?|وبعد ذلك؟ الجنّة والنار؟",
    "B:Sí, el Paraíso y el Infierno. Allah es perfectamente justo, pero también inmensamente misericordioso, y Su misericordia precede a Su ira.|نعم، الجنّة والنار. الله عدل تامّ، لكنّه أيضًا واسع الرحمة، ورحمته سبقت غضبه.",
    "A:¿Y qué pasa con alguien que nunca oyó hablar del islam?|وماذا عن شخص لم يسمع بالإسلام قطّ؟",
    "B:Es una pregunta seria y no quiero responderte a la ligera. Sé que Allah no castiga a nadie sin haberle hecho llegar antes el mensaje (Corán 17:15), pero los detalles prefiero consultarlos con alguien de conocimiento.|سؤال جادّ ولا أريد أن أجيبك عنه باستخفاف. أعلم أنّ الله لا يعذّب أحدًا قبل أن تبلغه الرسالة (سورة الإسراء: 15)، لكنّني أفضّل أن أسأل أهل العلم عن التفاصيل.",
    "A:Me parece una respuesta honesta. Pensar en todo esto da un poco de miedo.|تبدو لي إجابة صادقة. التفكير في كلّ هذا يخيف قليلًا.",
    "B:Es normal. A mí, pensar en la otra vida me motiva a aprovechar esta: a ser mejor persona y a acercarme a Allah. Si te interesa, en IslamHouse hay un libro breve sobre la vida después de la muerte.|هذا طبيعي. أمّا أنا فالتفكير في الآخرة يحفّزني على اغتنام هذه الحياة: أن أكون إنسانًا أفضل وأن أتقرّب إلى الله. وإن كان الأمر يهمّك ففي IslamHouse كتاب قصير عن الحياة بعد الموت."
  ] },

  { id: "cv71", lv: "B1", ic: "🧎", t: "Un adolescente pregunta por la oración", tar: "مراهق يسأل عن الصلاة", roles: ["المراهق", "الداعية"], d: [
    "A:Oye, Idris, ¿por qué pones la frente en el suelo cuando rezas?|اسمع يا إدريس، لماذا تضع جبهتك على الأرض حين تصلّي؟",
    "B:Buena pregunta, Hugo. Esa postura se llama postración. Es la forma de mostrar la mayor humildad ante Allah.|سؤال جيّد يا هوغو. تلك الهيئة تسمّى السجود. إنّها أعظم صور التواضع أمام الله.",
    "A:¿Y no te da vergüenza que te vean?|ألا تخجل أن يراك الناس؟",
    "B:Al principio un poco, cuando tenía tu edad. Pero luego entendí que no tengo por qué avergonzarme de hablar con mi Creador.|في البداية قليلًا، حين كنتُ في عمرك. لكنّني فهمتُ بعد ذلك أنّه لا داعي لأن أخجل من مناجاة خالقي.",
    "A:¿De verdad rezas cinco veces al día? ¿Incluso de madrugada?|هل تصلّي حقًّا خمس مرّات في اليوم؟ حتى في الفجر؟",
    "B:Sí, la primera es antes de que salga el sol. Cuesta levantarse, no te voy a mentir, pero empiezo el día con mucha paz.|نعم، أولاها قبل طلوع الشمس. الاستيقاظ صعب، لن أكذب عليك، لكنّني أبدأ يومي بسكينة كبيرة.",
    "A:¿Y qué dices cuando rezas? ¿Pides cosas?|وماذا تقول حين تصلّي؟ هل تطلب أشياء؟",
    "B:Recito partes del Corán en árabe, sobre todo la primera sura, Al-Fātiha, y alabo a Allah. Y sí, también le pido cosas: ayuda en los exámenes, salud para mi familia...|أتلو أجزاءً من القرآن بالعربية، ولا سيّما السورة الأولى، الفاتحة، وأحمد الله وأثني عليه. ونعم، أسأله أشياء أيضًا: العون في الامتحانات، والصحّة لأسرتي...",
    "A:¿En árabe? Pero tú hablas español.|بالعربية؟ لكنّك تتكلّم الإسبانية.",
    "B:Sí, la oración se hace en árabe en todo el mundo. Pero fuera de la oración puedes pedirle a Allah en tu propio idioma; Él entiende todas las lenguas.|نعم، تُؤدّى الصلاة بالعربية في العالم كلّه. أمّا خارج الصلاة فيمكنك أن تدعو الله بلغتك؛ فهو يعلم كلّ اللغات.",
    "A:Mola. ¿Puedo verte rezar algún día, sin molestar?|رائع. هل يمكنني أن أراك تصلّي يومًا ما دون أن أزعجك؟",
    "B:Claro, puedes sentarte detrás en silencio, y luego te explico lo que no entiendas. Pero pide permiso a tus padres antes de venir a la mezquita, ¿vale?|بالطبع، يمكنك أن تجلس خلفنا بصمت، ثمّ أشرح لك ما لا تفهمه. لكن استأذن والديك قبل أن تأتي إلى المسجد، اتّفقنا؟"
  ] },

  { id: "cv72", lv: "B1", ic: "📗", t: "Quiero leer el Corán", tar: "أريد قراءة القرآن", roles: ["المهتمّة", "الداعية"], d: [
    "A:Sumaya, me gustaría leer el Corán, pero no sé por dónde empezar.|سميّة، أودّ أن أقرأ القرآن، لكنّني لا أعرف من أين أبدأ.",
    "B:¡Qué buena noticia, Elena! Me alegra mucho. ¿Lo quieres leer por curiosidad o buscas algo en concreto?|يا له من خبر جميل يا إيلينا! يسعدني ذلك كثيرًا. هل تريدين قراءته فضولًا أم تبحثين عن شيء محدّد؟",
    "A:Un poco de todo. Quiero entender en qué creéis, directamente de la fuente.|قليلًا من كلّ شيء. أريد أن أفهم بماذا تؤمنون، من المصدر مباشرة.",
    "B:Me parece estupendo. Primero, ten en cuenta que en español leerás una traducción de los significados, no el Corán en su lengua original.|يبدو لي ذلك رائعًا. أوّلًا، ضعي في حسبانكِ أنّكِ ستقرئين بالإسبانية ترجمة للمعاني، لا القرآن بلغته الأصلية.",
    "A:¿Y qué traducción me recomiendas?|وأيّ ترجمة تنصحينني بها؟",
    "B:En QuranEnc.com hay traducciones al español revisadas por especialistas, con notas que explican el contexto. Puedes leerla gratis en el móvil.|في موقع QuranEnc.com ترجمات إسبانية راجعها متخصّصون، مع حواشٍ تشرح السياق. يمكنكِ قراءتها مجّانًا على الهاتف.",
    "A:¿Lo leo desde la primera página hasta el final, como una novela?|هل أقرؤه من الصفحة الأولى إلى النهاية كالرواية؟",
    "B:Puedes, pero el Corán no está ordenado como un relato. A muchas personas les ayuda empezar por suras breves o por historias como la de José (Corán 12) o la de María (Corán 19).|يمكنكِ ذلك، لكنّ القرآن ليس مرتّبًا كقصّة متسلسلة. كثير من الناس يساعدهم أن يبدؤوا بالسور القصيرة، أو بقصص مثل قصّة يوسف (السورة 12) أو قصّة مريم (السورة 19).",
    "A:¿Y si encuentro algo que no entiendo o que me choca?|وإن وجدتُ شيئًا لا أفهمه أو يصدمني؟",
    "B:Apúntalo y lo hablamos. Muchas aleyas tienen un contexto que las explica. Y si yo no sé la respuesta, lo consultaré con alguien de conocimiento, sin inventarme nada.|دوّنيه ونتحدّث فيه. كثير من الآيات لها سياق يوضّحها. وإن لم أعرف الجواب سأسأل أحد أهل العلم دون أن أختلق شيئًا.",
    "A:Gracias por no presionarme. A veces la gente se pone muy insistente.|شكرًا لأنّكِ لا تضغطين عليّ. أحيانًا يصبح الناس ملحّين جدًّا.",
    "B:Leer el Corán es un camino personal. Tómatelo con calma y con la mente abierta, y si en algún momento quieres comentarlo, aquí estoy.|قراءة القرآن رحلة شخصية. خذيها بهدوء وبعقل منفتح، وإن رغبتِ في أيّ وقت في الحديث عنه فأنا هنا."
  ] },

  { id: "cv73", lv: "B2", ic: "👪", t: "«Me da miedo la reacción de mi familia»", tar: "«أخشى ردّة فعل أسرتي»", roles: ["المهتمّ بالإسلام", "الداعية"], d: [
    "A:Rashid, llevo meses leyendo sobre el islam y creo que es la verdad. Pero tengo miedo de lo que dirá mi familia.|رشيد، منذ أشهر وأنا أقرأ عن الإسلام، وأظنّ أنّه الحقّ. لكنّني خائف ممّا ستقوله أسرتي.",
    "B:Gracias por confiar en mí para contarme algo tan personal. ¿Qué es lo que más te preocupa?|شكرًا لثقتك بي حتى تخبرني بأمر شخصي كهذا. ما أكثر ما يقلقك؟",
    "A:Mi madre es muy católica. Creo que lo vivirá como si la rechazara a ella.|أمّي كاثوليكية متديّنة جدًّا. أظنّ أنّها ستشعر وكأنّني أرفضها هي.",
    "B:Es un miedo muy comprensible. Pero hacerse musulmán no significa alejarse de los padres. Al contrario: el Corán ordena tratarlos con bondad, aunque no compartan tu fe (Corán 31:14-15).|إنّه خوف مفهوم جدًّا. لكنّ الدخول في الإسلام لا يعني الابتعاد عن الوالدين. بل على العكس: القرآن يأمر بالإحسان إليهما ومصاحبتهما بالمعروف وإن لم يشاركاك دينك (سورة لقمان: 14-15).",
    "A:¿De verdad? Pensaba que tendría que cortar con ellos.|حقًّا؟ كنت أظنّ أنّني سأضطرّ إلى قطع علاقتي بهم.",
    "B:En absoluto. Seguirías siendo su hijo, y deberías ser aún más cariñoso y paciente con ellos que antes.|أبدًا. ستبقى ابنهم، وينبغي أن تكون أكثر برًّا ولطفًا وصبرًا معهم من ذي قبل.",
    "A:¿Y cómo se lo cuento? ¿Tengo que hacerlo enseguida?|وكيف أخبرهم؟ هل يجب أن أفعل ذلك فورًا؟",
    "B:Eso depende mucho de tu situación, y no quiero darte una respuesta general. Te propongo que lo hablemos con el imam de la mezquita, que tiene experiencia acompañando a personas en tu caso.|هذا يعتمد كثيرًا على وضعك، ولا أريد أن أعطيك جوابًا عامًّا. أقترح أن نتحدّث في الأمر مع إمام المسجد، فلديه خبرة في مرافقة أشخاص في مثل حالتك.",
    "A:Me tranquiliza saber que no estaría solo.|يطمئنني أن أعرف أنّني لن أكون وحدي.",
    "B:No lo estarás. Pero quiero que sepas algo: la decisión es solo tuya, entre tú y Allah. Nadie debe presionarte, ni yo ni nadie; el Corán enseña que nadie puede ser obligado a abrazar la fe (Corán 2:256).|لن تكون وحدك. لكن أريدك أن تعرف شيئًا: القرار قرارك وحدك، بينك وبين الله. لا ينبغي أن يضغط عليك أحد، لا أنا ولا غيري؛ فالقرآن يقرّر أنّه لا يُكرَه أحد على الدين (سورة البقرة: 256).",
    "A:Gracias, Rashid. Necesito pensarlo un poco más.|شكرًا يا رشيد. أحتاج إلى أن أفكّر في الأمر أكثر قليلًا.",
    "B:Pídele a Allah que te guíe; Él escucha a quien le busca con sinceridad. Y recuerda que no tienes que elegir entre la fe y tu familia. Yo seguiré siendo tu amigo decidas lo que decidas.|اسأل الله أن يهديك؛ فهو يسمع من يطلبه بصدق. وتذكّر أنّك لست مضطرًّا إلى الاختيار بين الإيمان وأسرتك. وسأبقى صديقك أيًّا كان قرارك."
  ] },

  { id: "cv74", lv: "B1", ic: "🤝", t: "El primer viernes de un nuevo musulmán", tar: "أوّل جمعة لمسلم جديد", roles: ["الداعية", "المسلم الجديد"], d: [
    "A:¡Assalamu alaikum, Lucas! Hoy es tu primer viernes como musulmán. ¿Cómo estás?|السلام عليكم يا لوكاس! اليوم أوّل جمعة لك وأنت مسلم. كيف حالك؟",
    "B:¡Wa alaikum assalam! Un poco nervioso, la verdad. No sé muy bien qué hacer.|وعليكم السلام! متوتّر قليلًا في الحقيقة. لا أعرف جيّدًا ماذا أفعل.",
    "A:Tranquilo, estaré a tu lado todo el tiempo. Lo mejor es llegar un poco antes.|اطمئنّ، سأكون بجانبك طوال الوقت. الأفضل أن نصل قبل الموعد بقليل.",
    "B:Esta mañana me he duchado y me he puesto mi mejor ropa. ¿Está bien así?|هذا الصباح اغتسلتُ ولبستُ أفضل ثيابي. هل هذا جيّد؟",
    "A:¡Perfecto! Eso es lo que nos enseñó el Profeta Muhammad para el viernes. ¿Ya has hecho la ablución?|ممتاز! هذا ما علّمنا إيّاه النبي ﷺ ليوم الجمعة. هل توضّأتَ؟",
    "B:Sí, en casa, como me enseñaste. ¿Qué pasa primero en la mezquita?|نعم، في البيت كما علّمتني. ماذا يحدث أوّلًا في المسجد؟",
    "A:Al entrar, si hay tiempo, rezamos dos rakaʿas de saludo a la mezquita. Luego el imam sube al minbar y da el sermón.|عند الدخول، إن كان هناك وقت، نصلّي ركعتين تحيّة المسجد. ثمّ يصعد الإمام المنبر ويلقي الخطبة.",
    "B:¿Y si no entiendo el sermón? Puede que sea en árabe.|وإن لم أفهم الخطبة؟ قد تكون بالعربية.",
    "A:En nuestra mezquita el imam resume el sermón en español. Lo importante es escuchar en silencio, sin hablar ni mirar el móvil.|في مسجدنا يلخّص الإمام الخطبة بالإسبانية. المهمّ أن تستمع بصمت، دون كلام ولا نظر إلى الهاتف.",
    "B:Entendido. ¿Y después del sermón?|مفهوم. وبعد الخطبة؟",
    "A:Rezamos juntos dos rakaʿas detrás del imam. Tú solo haz lo mismo que la persona que tengas al lado.|نصلّي جماعةً ركعتين خلف الإمام. أنت فقط افعل ما يفعله من بجانبك.",
    "B:Gracias, hermano. Me hace mucha ilusión rezar con tanta gente por primera vez.|شكرًا يا أخي. أنا متشوّق جدًّا للصلاة مع هذا العدد الكبير من الناس لأوّل مرّة."
  ] },

  { id: "cv75", lv: "B1", ic: "🌿", t: "¿Quién fue el Profeta Muhammad?", tar: "من هو النبي محمد ﷺ؟", roles: ["الجارة", "الداعية"], d: [
    "A:Amal, siempre que mencionas a Muhammad dices algo en árabe. ¿Qué significa?|أمل، كلّما ذكرتِ محمدًا قلتِ شيئًا بالعربية. ماذا يعني؟",
    "B:Digo «la paz y las bendiciones de Allah sean con él». Es una forma de mostrarle amor y respeto.|أقول «صلّى الله عليه وسلّم». إنّها طريقة لإظهار المحبّة والاحترام له.",
    "A:¿Quién era exactamente? Sé muy poco de él.|من كان بالضبط؟ أعرف عنه القليل جدًّا.",
    "B:Nació en La Meca hacia el año 570. Su padre murió antes de que naciera y su madre cuando era niño. Trabajó como pastor y luego como comerciante.|وُلد في مكّة نحو عام 570. توفّي أبوه قبل أن يولد، وتوفّيت أمّه وهو طفل. وعمل راعيًا للغنم ثمّ تاجرًا.",
    "A:¿Y cómo se convirtió en profeta?|وكيف أصبح نبيًّا؟",
    "B:A los cuarenta años, mientras se retiraba a adorar a Allah en una cueva cerca de La Meca, recibió la primera revelación por medio del ángel Gabriel.|في الأربعين من عمره، بينما كان يتعبّد في غار قرب مكّة، نزل عليه أوّل الوحي بواسطة الملَك جبريل عليه السلام.",
    "A:¿Qué tipo de persona era?|أيّ نوع من الأشخاص كان؟",
    "B:Incluso antes de ser profeta, la gente de La Meca lo llamaba «el digno de confianza». Era humilde, ayudaba en casa, visitaba a los enfermos y era cariñoso con los niños.|حتى قبل النبوّة، كان أهل مكّة يلقّبونه «الأمين». كان متواضعًا، يساعد في بيته، ويعود المرضى، ويلاطف الأطفال.",
    "A:¿Y para vosotros es el único profeta?|وهل هو عندكم النبي الوحيد؟",
    "B:No. Creemos en todos los profetas, como Abraham, Moisés y Jesús. Muhammad es el último de ellos (Corán 33:40), enviado como misericordia para toda la humanidad (Corán 21:107).|لا. نؤمن بجميع الأنبياء، مثل إبراهيم وموسى وعيسى عليهم السلام. ومحمد ﷺ آخرهم (سورة الأحزاب: 40)، أُرسل رحمةً للعالمين (سورة الأنبياء: 107).",
    "A:Me gustaría saber más sobre su vida.|أودّ أن أعرف المزيد عن حياته.",
    "B:Te recomiendo una biografía breve que hay en IslamHouse en español. Y si quieres, después la comentamos juntas con un café.|أنصحكِ بسيرة مختصرة موجودة في IslamHouse بالإسبانية. وإن أحببتِ نناقشها معًا بعد ذلك على فنجان قهوة."
  ] },

  { id: "cv76", lv: "B1", ic: "🥩", t: "¿Qué es la comida halal?", tar: "ما الطعام الحلال؟", roles: ["الزميل", "الداعية"], d: [
    "A:Oye, Samir, voy a organizar una barbacoa en casa el domingo. ¿Qué puedes comer y qué no?|اسمع يا سمير، سأنظّم حفل شواء في بيتي يوم الأحد. ماذا تستطيع أن تأكل وماذا لا تستطيع؟",
    "B:¡Qué amable por preguntar, Jorge! Lo principal es que no como cerdo ni nada que lleve alcohol.|ما ألطفك لأنّك سألت يا خورخي! الأهمّ أنّني لا آكل لحم الخنزير ولا أيّ شيء فيه كحول.",
    "A:¿Y el pollo o la ternera normales?|والدجاج أو لحم العجل العاديّان؟",
    "B:La carne tiene que ser halal, es decir, de un animal sacrificado según las normas islámicas, mencionando el nombre de Allah.|يجب أن يكون اللحم حلالًا، أي من حيوان ذُبح وفق الأحكام الإسلامية مع ذكر اسم الله عليه.",
    "A:¿Y dónde se compra esa carne?|ومن أين يُشترى هذا اللحم؟",
    "B:En carnicerías halal. Hay una cerca de la estación. Si quieres, te acompaño el sábado.|من محلّات الجزارة الحلال. هناك محلّ قرب المحطّة. إن أردتَ رافقتُك يوم السبت.",
    "A:Genial. ¿Y por qué no coméis cerdo?|رائع. ولماذا لا تأكلون الخنزير؟",
    "B:Porque Allah lo prohibió en el Corán (Corán 2:173). Algunos hablan de razones de salud, pero para nosotros basta con que sea un mandato de Allah; confiamos en Su sabiduría.|لأنّ الله حرّمه في القرآن (سورة البقرة: 173). بعض الناس يتحدّثون عن أسباب صحّية، لكن يكفينا أنّه أمر من الله؛ ونحن نثق بحكمته.",
    "A:Entendido. ¿Y las gominolas? A mis hijos les encantan y quería comprar para todos.|مفهوم. وماذا عن حلوى الجيلي؟ أطفالي يحبّونها، وأردتُ أن أشتري للجميع.",
    "B:Muchas llevan gelatina de cerdo, así que normalmente las evitamos. Sobre otros tipos de gelatina hay detalles que no conozco bien; prefiero consultarlo antes de decirte algo.|كثير منها يحتوي على جيلاتين الخنزير، لذلك نتجنّبها عادةً. أمّا أنواع الجيلاتين الأخرى ففيها تفاصيل لا أعرفها جيّدًا؛ أفضّل أن أسأل قبل أن أقول لك شيئًا.",
    "A:Sin problema. Compraré fruta y zumos, que gustan a todos.|لا مشكلة. سأشتري فاكهة وعصائر، فالجميع يحبّها.",
    "B:¡Perfecto! Y yo llevo un postre que hace mi madre. Gracias por pensar en mí; en el islam, la hospitalidad es algo muy valorado.|ممتاز! وأنا أُحضر حلوى تصنعها أمّي. شكرًا لأنّك فكّرتَ فيّ؛ ففي الإسلام لإكرام الضيف مكانة كبيرة."
  ] },

  { id: "cv77", lv: "B2", ic: "🌍", t: "¿Por qué hay tantas religiones?", tar: "لماذا توجد أديان كثيرة؟", roles: ["الصديقة", "الداعية"], d: [
    "A:Hay algo que no me cuadra, Bashir. Si Dios existe, ¿por qué hay tantas religiones distintas?|هناك شيء لا أفهمه يا بشير. إن كان الله موجودًا فلماذا توجد أديان مختلفة كثيرة؟",
    "B:Es una pregunta que se hace mucha gente sincera. ¿Tú qué piensas?|إنّه سؤال يطرحه كثير من الباحثين الصادقين. ما رأيكِ أنتِ؟",
    "A:Que quizá todas son inventos humanos para explicar lo que no entendemos.|أنّها ربّما كلّها اختراعات بشرية لتفسير ما لا نفهمه.",
    "B:Entiendo por qué llegas a esa conclusión. Yo lo veo de otra manera: creo que Dios envió profetas a muchos pueblos a lo largo de la historia, y que todos transmitieron el mismo mensaje esencial (Corán 16:36).|أفهم لماذا تصلين إلى هذا الاستنتاج. أمّا أنا فأراه بطريقة أخرى: أؤمن بأنّ الله أرسل أنبياء إلى أمم كثيرة عبر التاريخ، وأنّهم جميعًا بلّغوا الرسالة الجوهرية نفسها (سورة النحل: 36).",
    "A:¿Qué mensaje?|أيّ رسالة؟",
    "B:Adorar solo a Dios, sin asociarle nada, y hacer el bien. Con el tiempo, la gente fue añadiendo o cambiando cosas, y así surgieron las diferencias.|عبادة الله وحده دون أن يُشرَك به شيء، وفعل الخير. ومع مرور الزمن أخذ الناس يضيفون أشياء أو يغيّرونها، فنشأت الاختلافات.",
    "A:Pero cada religión dice que la suya es la verdadera.|لكنّ كلّ دين يقول إنّه هو الحقّ.",
    "B:Es verdad, y no te voy a pedir que me creas solo porque lo digo yo. Lo honesto es investigar con la mente abierta y comparar los argumentos.|هذا صحيح، ولن أطلب منكِ أن تصدّقيني لمجرّد أنّني أقول ذلك. الأمانة أن تبحثي بعقل منفتح وتقارني الحجج.",
    "A:¿Y no te parece arrogante pensar que tu religión es la verdadera?|ألا يبدو لك من الغرور أن تعتقد أنّ دينك هو الحقّ؟",
    "B:Lo entiendo así: si creo algo, es porque me parece verdad. Pero eso no me da derecho a despreciar a nadie. Respeto profundamente tu libertad de buscar.|أفهم الأمر هكذا: إن آمنتُ بشيء فلأنّه يبدو لي حقًّا. لكنّ هذا لا يمنحني حقّ احتقار أحد. وأنا أحترم بعمق حرّيتكِ في البحث.",
    "A:Me parece una postura muy respetuosa.|يبدو لي موقفًا محترمًا جدًّا.",
    "B:Gracias. Si te apetece, te paso un libro breve de IslamHouse que explica el islam desde lo más básico. Léelo con espíritu crítico y luego lo hablamos.|شكرًا. إن رغبتِ أرسلتُ لكِ كتابًا قصيرًا من IslamHouse يشرح الإسلام من أساسيّاته. اقرئيه بعين ناقدة ثمّ نتحدّث فيه."
  ] },

  { id: "cv78", lv: "B2", ic: "🌧️", t: "¿Puede Dios perdonarme?", tar: "هل يمكن أن يغفر الله لي؟", roles: ["الصديق", "الداعية"], d: [
    "A:Zakaria, ¿tú crees que Dios puede perdonar a alguien que ha hecho cosas muy malas?|زكريّا، هل تعتقد أنّ الله يمكن أن يغفر لشخص فعل أشياء سيّئة جدًّا؟",
    "B:Lo creo con todo el corazón. ¿Lo preguntas por algo en particular? Solo si quieres contármelo.|أؤمن بذلك من كلّ قلبي. هل تسأل عن أمر بعينه؟ فقط إن أردتَ أن تخبرني.",
    "A:Digamos que en el pasado hice daño a gente y no me siento orgulloso. A veces pienso que ya no tengo arreglo.|لنقل إنّني في الماضي آذيتُ أناسًا ولستُ فخورًا بذلك. أحيانًا أظنّ أنّه لا أمل في إصلاحي.",
    "B:Gracias por tu confianza. En el islam nadie debe perder la esperanza en la misericordia de Allah. El Corán enseña que Allah perdona todos los pecados a quien se arrepiente sinceramente (Corán 39:53).|شكرًا لثقتك. في الإسلام لا ينبغي لأحد أن يقنط من رحمة الله. والقرآن يعلّم أنّ الله يغفر الذنوب جميعًا لمن تاب توبة صادقة (سورة الزمر: 53).",
    "A:¿Y necesito confesarme con alguien, como con un sacerdote?|وهل أحتاج إلى الاعتراف أمام أحد، كما يُفعل أمام الكاهن؟",
    "B:No. En el islam te diriges directamente a Allah, sin intermediarios. El arrepentimiento es entre tú y Él.|لا. في الإسلام تتوجّه إلى الله مباشرة دون وسطاء. التوبة بينك وبينه.",
    "A:¿Y cómo se arrepiente uno de verdad?|وكيف يتوب المرء حقًّا؟",
    "B:Dejando el mal que hacía, lamentándolo sinceramente y decidiendo no volver a hacerlo. Y si hiciste daño a alguien, intentando reparar lo que se pueda o pidiéndole perdón.|بأن يترك الذنب الذي كان يفعله، ويندم عليه صادقًا، ويعزم على ألّا يعود إليه. وإن كنتَ آذيتَ أحدًا فبأن تحاول إصلاح ما يمكن أو تطلب منه المسامحة.",
    "A:Eso es difícil, pero tiene sentido. ¿Y si alguien se hace musulmán? ¿Qué pasa con su pasado?|هذا صعب لكنّه منطقي. وإن أسلم شخص ما، فماذا عن ماضيه؟",
    "B:El Profeta Muhammad enseñó que el islam borra lo que había antes. Es como empezar una página nueva.|علّمنا النبي ﷺ أنّ الإسلام يهدم ما كان قبله. إنّه كبدء صفحة جديدة.",
    "A:Una página nueva... Me cuesta creer que sea tan sencillo.|صفحة جديدة... يصعب عليّ أن أصدّق أنّ الأمر بهذه البساطة.",
    "B:La misericordia de Allah es más grande que cualquier error humano. Si quieres, otro día te cuento más sobre este tema y te paso algo para leer en IslamHouse.|رحمة الله أوسع من أيّ خطأ بشري. إن أردتَ حدّثتك يومًا آخر عن هذا الموضوع أكثر، وأرسلتُ لك شيئًا تقرؤه في IslamHouse."
  ] },

  { id: "cv79", lv: "B1", ic: "👋", t: "Cuando el otro no está interesado", tar: "حين لا يكون الطرف الآخر مهتمًّا", roles: ["الداعية", "الزميل"], d: [
    "A:Por cierto, Álex, el otro día me preguntaste por el islam. Te he traído un librito por si te apetece leerlo.|بالمناسبة يا أليكس، سألتني قبل أيام عن الإسلام. أحضرتُ لك كتيّبًا إن رغبتَ في قراءته.",
    "B:Ah, gracias, Anwar... Pero, si te soy sincero, solo preguntaba por curiosidad. No me interesa mucho la religión.|آه، شكرًا يا أنور... لكن إن أردتَ الصراحة، كنتُ أسأل فضولًا فقط. الدين لا يهمّني كثيرًا.",
    "A:Lo entiendo perfectamente, y te agradezco que me lo digas con claridad.|أفهم ذلك تمامًا، وأشكرك لأنّك تقول لي ذلك بوضوح.",
    "B:No te lo tomes a mal, ¿eh? No tengo nada en contra de los musulmanes.|لا تسئ فهمي. ليس لديّ شيء ضدّ المسلمين.",
    "A:Para nada. Cada persona tiene su ritmo y sus prioridades. Nuestra amistad no depende de eso.|أبدًا. لكلّ شخص إيقاعه وأولويّاته. وصداقتنا لا تتوقّف على ذلك.",
    "B:Me alegra oír eso. Pensaba que te ibas a molestar.|يسعدني سماع ذلك. ظننتُ أنّك ستنزعج.",
    "A:¿Molestarme? Al contrario. En mi religión no se obliga a nadie. Yo solo comparto lo que creo, con respeto, cuando alguien quiere escucharlo.|أنزعج؟ بالعكس. في ديني لا يُكرَه أحد. أنا فقط أشارك ما أؤمن به، باحترام، حين يرغب أحد في سماعه.",
    "B:Pues te lo agradezco. Mucha gente no reacciona así.|إذن أشكرك على ذلك. كثير من الناس لا يتصرّفون هكذا.",
    "A:Me guardo el libro, entonces. Si algún día cambias de idea, ya sabes dónde encontrarme.|سأحتفظ بالكتاب إذن. وإن غيّرتَ رأيك يومًا فأنت تعرف أين تجدني.",
    "B:Trato hecho. Oye, ¿seguimos con lo del partido del sábado?|اتّفقنا. اسمع، هل ما زلنا على موعد المباراة يوم السبت؟",
    "A:¡Claro! Allí estaré. Y esta vez el bocadillo lo pago yo.|بالطبع! سأكون هناك. وهذه المرّة الشطيرة على حسابي.",
    "B:¡Genial! Eres un gran amigo, Anwar.|رائع! أنت صديق رائع يا أنور."
  ] }
]);
